L["Apply the sharer's fonts, custom colours, dark mode, accent colour and UI scale. Off = keep your own global look and scale; only the selected modules' settings come in."] = "套用分享者的字型、自訂顏色、深色模式、強調色與介面縮放。停用＝保留你自己的全域外觀與縮放；只匯入所選模組的設定。"
