L["Blizzard's own character sheet with the EllesmereUI stats, slot text and socket panel added; the Calc tab stays with the EllesmereUI look."] = "暴雪原生的角色面板，加上 EllesmereUI 的屬性、欄位文字與插槽面板；計算分頁維持 EllesmereUI 外觀。"
