L["Target Cast Bar Target Size"]   = "目標施法條目標大小"
L["Target Cast Bar Texture"]       = "目標施法條材質"
L["Target Cast Bar Timer Size"]    = "目標施法條計時器大小"
L["Target Distance Text Size"]     = "目標距離文字大小"
L["Targeted Bars Name Size"]       = "目標法術條名稱大小"
L["Targeted Bars Target Size"]     = "目標法術條目標大小"
L["Targeted Bars Texture"]         = "目標法術條材質"
L["Targeted Bars Timer Size"]      = "目標法術條計時器大小"
L["TellMeWhen overlaps with EllesmereUI's core positional architecture. If you ONLY use for sound alerts it should be okay but may still cause issues."] = "TellMeWhen 與 EllesmereUI 的核心定位架構重疊。若你只拿它來做音效警示應該還好，但仍可能造成問題。"
L["TEXT DISPLAY"]                  = "文字顯示"
L["Text Scale (per data bar)"]     = "文字縮放（各資訊列）"
L["Texture for every unit frame cast bar. Inherit follows each unit's bar texture."] = "所有單位框架施法條的材質。「繼承」會沿用各單位的長條材質。"
L["Texture for the class resource bar."] = "職業資源條的材質。"
L["Texture for the health, power and class resource bars."] = "生命、能量與職業資源條所使用的材質。"
L["Textures"]                      = "材質"
L["That setting is stored by list position and can't be safely overridden."] = "該設定是依清單位置儲存的，無法安全地覆寫。"
L["The active override's Buff Manager is bound to the open page. Leave the Buff Manager tab to switch overrides."] = "目前啟用的覆寫其增益效果管理器已綁定至開啟中的頁面。請離開增益效果管理器分頁以切換覆寫。"
L["The active override's custom %s is bound to this page. Leave the %s tab to switch to another override."] = "目前啟用的覆寫，其自訂 %s 綁定在此頁面。離開「%s」分頁才能切換到其他覆寫。"
L["The background colour behind Dark Mode bars (Unit Frames, Raid Frames, Resource Bars)."] = "深色模式下，各種類型條（單位框架、團隊框架、資源條）的底色。"
L["The Cooldown Manager can do far more than show cooldowns, it also has per-spell settings, bar glows, tracking bars and more! Check out some tips and tricks for getting more from it."] = "冷卻管理器能做的遠不只是顯示冷卻，它還有各法術專屬設定、長條發光、追蹤條等等！來看看能讓它發揮更多效用的技巧與訣竅。"
L["The display language for the EllesmereUI options panel. Auto follows your game client. Untranslated text falls back to English."] = "EllesmereUI 選項面板的顯示語言。「自動」會跟著你的遊戲客戶端走。沒翻譯到的文字會顯示英文。"
L["The exact inverse of Skyriding (Airborne): anything that is not airborne on a glide-capable mount or flight form, standing on the ground included."] = "「飛龍騎術（空中）」的完全相反：只要不是騎乘可滑翔的坐騎或飛行形態且位於空中，都算符合，包含站在地面上時。"
L["The flat fill colour bars use when Dark Mode is enabled (Unit Frames, Raid Frames, Resource Bars)."] = "當啟用深色模式時（單位框架、團隊框架、資源條）使用的純色填充顏色。"
L["The original frames, rings and slots where the game has them, with EllesmereUI's features."] = "在遊戲原本就有的地方使用原始的框架、圓環與欄位，搭配 EllesmereUI 的功能。"
L["The override group '%s' already provides the custom unlock mode for your current spec. Customize it there, or remove this spec from that group."] = "覆寫群組「%s」已為你目前的專精提供自訂解鎖模式。請在該處自訂，或將此專精從該群組移除。"
L["The personal resource display's bar frame, or the classic cast bar frame, on the health, power and class resource bars, with every EllesmereUI bar feature."] = "在生命、能量與職業資源條上使用個人資源顯示的計量條外框或經典的施法條外框，並保有 EllesmereUI 的所有計量條功能。"
L["The scriptProfile CVar is enabled."] = "已啟用 scriptProfile CVar。"
L["The taintLog and scriptProfile CVars are enabled."] = "已啟用 taintLog 與 scriptProfile CVar。"
L["The taintLog CVar is enabled."] = "已啟用 taintLog CVar。"
L["These are the same settings found on each module's own pages, not separate ones."] = "這些就是各模組自己頁面上的同一批設定，並非另外一組。"
L["These settings prioritize frame rate and visual clarity over environmental detail. Textures stay high quality so your character and the world still look perfect."] = "這些設定將幀率與畫面清晰度置於環境細節之上。材質維持高品質，因此你的角色與整個世界依然看起來完美。"
L["These specs hold override values that no group's editing mode can reach anymore (left behind by membership changes). They still apply. Remove one to return that spec to the shared default."] = "這些專精持有的覆寫值已無法由任何群組的編輯模式存取（成員變更後遺留下來的）。它們仍會生效。移除其中一項即可讓該專精回到共用的預設值。"
L["This bar will only show if you have an enemy targeted"] = "此列僅在你鎖定敵人目標時才會顯示"
L["This cannot be undone. Consider exporting this profile as a backup first."] = "此動作無法復原。建議先將此設定檔匯出備份。"
L["This cannot be undone. Export your own profile as a backup first."] = "此動作無法復原。請先將你自己的設定檔匯出備份。"
L["This condition is coming in a future update."] = "此條件將於未來的更新中推出。"
L["This conditional is not active right now. Meet one of its conditions first (for example, enter the dungeon) so you can arrange the layout in its real context."] = "此條件目前未啟用。請先滿足其中一項條件（例如進入該地城），才能在實際情境中安排版面配置。"
L["This element cannot use group-based visibility."] = "此元素無法使用群組式可見性。"
L["This element shows as soon as ONE Show condition matches. Hide keeps its meaning in both match modes: a checked Hide always hides, on every row."] = "只要有一項「顯示」條件符合，此元素就會顯示。「隱藏」在兩種符合模式下的意義不變：勾選的「隱藏」一律隱藏，每一列皆然。"
L["This element will only show while you are inside a house or plot"] = "此元件僅會在你位於房屋或地產內時顯示"
L["This element will only show while you are mounted"] = "此元件僅會在你騎乘時顯示"
L["This export includes cross profile settings that will overwrite the importing user's settings including Quality of Life, Hovercast and more that should typically not be shared with standard profiles. THIS IS NOT RECOMMENDED for public sharing of profiles."] = "此匯出包含跨設定檔的設定，會覆寫匯入者的設定，其中包括「體驗優化」、「懸停施法」等通常不應隨一般設定檔分享的項目。強烈不建議用於公開分享設定檔。"
L["This feature optimizes your in-game graphics settings to give you the best combination of high FPS and visual clarity.\n\nYou can revert all changes at any time by clicking \"Restore My Settings\" which will appear after optimizing.\n\n\nWhat we change:\n\n"] = "此功能會最佳化你的遊戲內圖形設定，在高 FPS 與畫面清晰度之間取得最佳平衡。\n\n你隨時可以點擊最佳化後出現的「還原我的設定」來復原所有變更。\n\n\n我們會變更的項目：\n\n"
L["This group's custom Buff Manager can only be activated or edited while playing one of its specs."] = "此群組的自訂增益效果管理器只有在你使用其中一個專精時才能啟用或編輯。"
L["This group's custom Debuff Manager can only be activated or edited while playing one of its specs."] = "此群組的自訂減益效果管理器只有在使用其所屬專精時才能啟用或編輯。"
L["This is the Spell Queue Window, it helps with making sure you can't queue up too many spells at once which makes the game feel laggy. Recommended settings are generally a minimum of 200 + your local ping. If you are unsure of exactly what this setting does, leave it at 400."] = "此為「施法佇列視窗」設定，可避免一次排入過多法術而導致遊戲產生延遲感。建議設定值通常至少為 200 加上您的本地延遲。若您不確定此功能的作用，請保持預設值 400 即可。"
L["This module can't be overridden. Exit the override editing session to open it."] = "此模組無法被覆寫。請結束覆寫編輯工作階段後再開啟。"
L["This module is excluded from Spec Overrides."] = "此模組不納入專精覆寫。"
L["This option is only available for the Custom Color Theme"] = "此選項僅在自訂色彩主題下可用"
L["This page is excluded from overrides."] = "此頁面不納入覆寫。"
L["This permanently overwrites this profile's settings with the override '%s': its captured settings and its custom Unlock Mode and Buff Manager layouts (where present) become the profile's own baseline for every spec. ALL spec override groups on this profile are then deleted and the UI reloads. Conditional overrides are not affected."] = "這會用覆寫「%s」永久覆寫此設定檔的設定：其已擷取的設定，以及自訂解鎖模式與增益效果管理器的版面配置（若有），將成為此設定檔在所有專精上的自身基準。接著此設定檔上的所有專精覆寫群組都會被刪除，並重新載入介面。條件覆寫不受影響。"
L["This profile string does not carry any global settings."] = "此設定檔字串未包含任何全域設定。"
L["This profile string does not carry any Window & Tooltip Skins settings."] = "此設定檔字串未包含任何視窗與提示資訊外觀設定。"
L["This resets every EUI addon, not just the current one."] = "這會重設每一個 EUI 插件，而不只是目前這一個。"
L["This setting already has an override for %s"] = "此設定已有 %s 的覆寫"
L["This setting can't be overridden."] = "此設定無法被覆寫。"
L["This Setting Has Overrides"]    = "此設定有覆寫"
L["This spec's custom unlock mode is owned by '%s'. Customize it there, or remove the spec from that group."] = "此專精的自訂解鎖模式由「%s」擁有。請在該處自訂，或將此專精從該群組移除。"
L["This string is a FULL ACCOUNT export. It replaces your account-wide settings with the sender's, including Quality of Life, HoverCast bindings, Cooldown Manager spell setups, unlock anchors, UI scale, and profile keybinds -- not just a profile. Your other profiles are kept, but a profile with the same name is replaced."] = "此字串是「完整帳號」匯出。它會用分享者的設定取代你的帳號通用設定，包括「體驗優化」、「懸停施法」按鍵綁定、冷卻管理器法術設定、解鎖錨點、UI 縮放與設定檔快捷鍵——而不只是一個設定檔。你的其他設定檔會保留，但同名的設定檔會被取代。"
L["This will create a fully unique Buff Manager for this conditional group. Changes made to your default Buff Manager will no longer affect it."] = "這會為此條件群組建立一個完全獨立的增益效果管理器。之後對預設增益效果管理器所做的變更將不再影響它。"
L["This will create a fully unique Buff Manager for this override group. Changes made to your default Buff Manager will no longer affect these specs."] = "這會為此覆寫群組建立一個完全獨立的增益效果管理器。之後對預設增益效果管理器所做的變更將不再影響這些專精。"
L["This will create a fully unique Debuff Manager for this conditional group. Your current Debuff Manager settings are copied as its starting point, and changes made to your default Debuff Manager will no longer affect it."] = "這會為此條件群組建立一個完全獨立的減益效果管理器。系統會複製你目前的減益效果管理器設定作為起點，之後對預設減益效果管理器所做的變更將不再影響它。"
L["This will create a fully unique Debuff Manager for this override group. Your current Debuff Manager settings are copied as its starting point, and changes made to your default Debuff Manager will no longer affect these specs."] = "這會為此覆寫群組建立一個完全獨立的減益效果管理器。系統會複製你目前的減益效果管理器設定作為起點，之後對預設減益效果管理器所做的變更將不再影響這些專精。"
L["This will create a fully unique unlock mode for this conditional group. Changes made to your default unlock mode will no longer affect it."] = "這會為此條件群組建立一個完全獨立的解鎖模式。之後對預設解鎖模式所做的變更將不再影響它。"
L["This will create a fully unique unlock mode for this override group. Changes made to your default unlock mode will no longer affect these specs."] = "這會為此覆寫群組建立一個完全獨立的解鎖模式。之後對預設解鎖模式所做的變更將不再影響這些專精。"
L["This will not reset addon-specific Quick Setup."] = "這不會重設各插件專屬的快速設定。"
L["This will replace YOUR Blizz UI Enhanced settings (the Window Skins and Tooltips, Menus & Popups tabs) with the sharer's, across ALL of your profiles. Your current settings on those two tabs cannot be recovered afterward."] = "這會用分享者的設定取代你所有設定檔中的「暴雪介面增強」設定（「視窗外觀」與「提示資訊、選單與彈出視窗」兩個分頁）。你目前在這兩個分頁的設定事後將無法復原。"
L["Threat Meter"]                  = "仇恨統計"
L["THREAT METER"]                  = "仇恨統計"
L["Timer Background Texture"]      = "計時條背景材質"
L["Timer Bar Texture"]             = "計時條材質"
