L["Tracking Bar Name, Timer & Stacks Text (per bar)"] = "追蹤條名稱、計時器與層數文字（各條）"
L["Tracking Bar Texture & Border (per bar)"] = "追蹤條材質與邊框（各條）"
L["Tracking bar textures and icon borders"] = "追蹤條材質與圖示邊框"
L["Turns Dark Mode on or off for the class resource bar."] = "為職業資源條開啟或關閉深色模式。"
L["Turns Dark Mode on or off for Unit Frames and Raid Frames at once."] = "同時為單位框架與團隊框架開啟或關閉深色模式。"
L["Twitch"]                        = "Twitch"
L["Type \"%s\" to enable:"]        = "輸入「%s」以啟用："
L["Type /reload in chat to apply."] = "在聊天視窗輸入 /reload 以套用。"
L["Typeface for the M+ timer clock. Every other Mythic+ text uses the module font."] = "傳奇鑰石計時器時鐘所使用的字型。其餘所有傳奇鑰石文字都使用模組字型。"
L["Typeface for the quest tracker. This module-local pick wins over the module font override above."] = "任務追蹤所使用的字型。此模組內的選擇會覆蓋上方的模組字型設定。"
L["UI Accent Color"]               = "UI 強調色"
