L["UI Scale Issue: Profile was made at %1$d%%, yours is %2$d%%"] = "介面縮放比例不符：此設定檔是在縮放值 %1$d%% 下製作的，而您目前的縮放值為 %2$d%%"
L["UI Scale Options"]              = "介面縮放選項"
L["UI scale set to 0.5333. A reload is recommended."] = "UI 縮放已設為 0.5333。建議重新載入。"
