L["Unlock Mode is how you move and resize everything in EllesmereUI, and it is packed with tools: anchors, width matching, fallback anchors, per-group layouts. This video gets you fluent fast."] = "「解鎖模式」是你在 EllesmereUI 中移動所有元素、調整其大小的方式，而且工具非常齊全：錨點、寬度對齊、備用錨點、各群組專屬的版面配置。這支影片能讓你很快上手。"
L["Unlock Mode is where you can adjust\npositioning for all the elements of EllesmereUI"] = "解鎖模式讓你能夠調整\nEllesmereUI 所有元素的位置"
L["Unlock Mode Layout"]            = "解鎖模式版面配置"
L["Update Sync Group"]             = "更新同步群組"
L["Used by the movement alert's Bar display mode."] = "供移動警示的「條」顯示模式使用。"
L["VANILLA ART"]                   = "經典美術風格"
L["VIDEO GUIDE"]                   = "影片教學"
L["Video Guide"]                   = "影片教學"
L["Video Guide: Cooldown Manager"] = "影片教學：冷卻管理器"
L["Video Guide: Unlock Mode"]      = "影片教學：解鎖模式"
