L["What's new in EllesmereUI."]    = "EllesmereUI 的最新內容。"
L["While on a glide-capable mount, ground included, where Blizzard shows its vigor HUD. Skyriding (Airborne) additionally requires you to be flying."] = "騎乘可滑翔的坐騎時（含在地面時），也就是暴雪會顯示精力 HUD 的狀態。「飛龍騎術（空中）」則另外要求你正在飛行。"
L["While Party Mode is active. Party Mode can start in combat (Bloodlust); secure elements such as action bars then keep their current visibility until combat ends."] = "當小隊模式啟用時。小隊模式可能在戰鬥中啟動（嗜血）；此時快捷列等受保護的元素會維持目前的可見性，直到戰鬥結束。"
L["While resting, in a city or at an inn."] = "當你處於休息區域（城市或旅店）時。"
