L["XP, reputation and favor bar textures"] = "經驗值、聲望與房屋經驗值條材質"
L["You changed the default value of a setting that has overrides. Overrides keep their own values, so this change will not reach the specs or conditions they cover. To change it for an override, pick that override from the class glyph beside the module search bar and edit it there."] = "你變更的是一項「有覆寫」設定的預設值。覆寫會保留各自的數值，因此這次變更不會套用到它們涵蓋的專精或條件。若要為某個覆寫變更此設定，請從模組搜尋列旁的職業符號選取該覆寫，再到那裡編輯。"
L["Your current spec has an assigned profile so you cannot switch to another. Please unassign to switch."] = "你目前的專精已指派設定檔，因此無法切換至其他設定檔。請先解除指派再切換。"
L["Your current spec has its own custom Buff Manager, so conditional Buff Managers never apply to it."] = "你目前的專精有自己的自訂增益效果管理器，因此條件式的增益效果管理器永遠不會套用到它。"
L["Your current spec has its own custom Debuff Manager, so conditional Debuff Managers never apply to it."] = "你目前的專精有自己的自訂減益效果管理器，因此條件式減益效果管理器一律不會套用於它。"
L["Your current spec has its own custom unlock mode, so conditional unlock modes never apply to it. Swap to a spec without one to customize this."] = "你目前的專精有自己的自訂解鎖模式，因此條件式的解鎖模式永遠不會套用到它。請切換到沒有自訂解鎖模式的專精才能自訂此項。"
L["Your setup and every EllesmereUI feature carry over; only the look changes. Apply a style to every module in one click, or set each module below. Changing a style reloads the UI."] = "你的設定與 EllesmereUI 的所有功能都會保留，只有外觀改變。可一鍵將樣式套用至所有模組，或在下方逐一設定各模組。變更樣式會重新載入介面。"
L["Zone Text Scale"]               = "區域文字縮放"
L["|cff0cd29dLeft-click:|r |cffE0E0E0Toggle EllesmereUI|r"] = "|cff0cd29d左鍵點擊：|r |cffE0E0E0切換 EllesmereUI|r"
L["|cff0cd29dMiddle-click:|r |cffE0E0E0Hide Minimap Button|r"] = "|cff0cd29d中鍵點擊：|r |cffE0E0E0隱藏小地圖按鈕|r"
L["|cff0cd29dRight-click:|r |cffE0E0E0Enter Unlock Mode|r"] = "|cff0cd29d右鍵點擊：|r |cffE0E0E0進入解鎖模式|r"
