L["A friendly focus wins over the tank. The focus is checked at the moment you press it, also in combat."] = "友方專注目標優先於坦克。按下時才會檢查專注目標，戰鬥中也一樣。"
L["A group member to use as the tank. Empty uses the raid Main Tank, then the Dungeon Finder tank role. Updates out of combat."] = "作為坦克的隊伍成員。留空時使用團隊主坦克，其次為地城搜尋器的坦克職責。脫離戰鬥時更新。"
L["A line at every 10% and a tick at every 5% across the bar."] = "整條每 10% 一條線，每 5% 一個刻度。"
L["A raid control panel with ready check, pull timer and target markers. In a raid it only shows while you are the leader or an assistant, since none of its buttons work without that; in a party it always shows."] = "包含準備確認、開怪倒數與目標標記的團隊控制面板。在團隊中只有你是隊長或助理時才會顯示，因為沒有權限時其按鈕都無法使用；在小隊中則總是顯示。"
