L["Clears your focus when you click the focus frame this way. Works in combat, where the right-click menu cannot clear focus."] = "以此方式點擊專注目標框架時清除專注目標。戰鬥中也有效，而右鍵選單在戰鬥中無法清除專注目標。"
L["Close Edit Mode first, then try again."] = "請先關閉編輯模式，然後再試一次。"
