L["Compact Band puts markers, ready check and pull timer in one row you can resize in Unlock Mode. The other choices keep the window layouts."] = "精簡橫列將標記、準備確認與開怪倒數放在同一列，可在解鎖模式中調整大小。其他選項則保留視窗版面配置。"
L["Compact clock and FPS readout."] = "精簡的時鐘與 FPS 顯示。"
L["Completed quest XP shows ahead of the fill in green, incomplete quest XP after it in gold. Quests under collapsed quest log headers are not counted."] = "已完成任務的經驗值以綠色顯示在填充前方，未完成任務的經驗值以金色顯示在其後。收合的任務日誌標題下的任務不計入。"
