L["Completed Quests Only"] = "僅限已完成任務"
L["Countdown length in seconds. Compact Band uses First with Ctrl + Left Click, Second with Shift + Left Click, Third with Left Click, and Right Click stops the timer. Set a timer to 0 to disable that shortcut."] = "倒數秒數。精簡橫列中，Ctrl + 左鍵使用第一個，Shift + 左鍵使用第二個，左鍵使用第三個，右鍵停止計時。將計時器設為 0 即可停用該快捷操作。"
