L["Hide Until Usable: only shown while usable and off cooldown, such as Overpower or Victory Rush after a proc; low resources do not hide it. Hide Outside Form/Stance: only shown in the form or stance the spell needs, even on cooldown. Keep Place leaves the gap; the others close it."] = "可用前隱藏：僅在可用且未冷卻時顯示，例如觸發後的壓制或勝利衝擊；資源不足不會將其隱藏。不在形態/姿態時隱藏：僅在法術所需的形態或姿態中顯示，冷卻中也一樣。保留位置會留下空隙；其他選項則會補上空隙。"
L["Hides the Bloodlust and Heroism lockout debuffs."] = "隱藏嗜血與英雄氣概的冷卻減益效果。"
