L["Hovering a stat in the sidebar glows the equipped items that give it (Hit, Crit, Haste, Defense, Strength...)."] = "滑鼠移過側欄中的屬性時，提供該屬性的已裝備物品會發光（命中、致命一擊、加速、防禦、力量...）。"
L["Hunters and Rogues: an icon you click (or bind in Key Bindings > EllesmereUI Quality of Life) that casts Misdirection or Tricks of the Trade on your focus, else the tank, else a friendly target"] = "獵人與盜賊：點擊（或在 按鍵設定 > EllesmereUI 體驗優化 中綁定）的圖示，會對你的專注目標施放誤導或偷天換日，若無則對坦克，再無則對友方目標"
