L["Native"] = "原生"
L["Native: the client's dark square sweep. Shaped: a drawn sweep that follows round icons and takes the Swipe Color."] = "原生：用戶端的深色方形轉圈。塑形：繪製的轉圈，會貼合圓形圖示並使用轉圈顏色。"
