L["Percent of the end caps' normal size."] = "端飾正常大小的百分比。"
L["Picks an NPC's only dialog option for you."] = "自動為你選擇 NPC 唯一的對話選項。"
L["Player Buffs on Tooltips"] = "浮動提示顯示玩家增益"
L["Positive values move both end caps away from the bar."] = "正值會讓兩端端飾遠離條。"
