L["Raid Debuffs Filter"] = "團隊減益效果篩選"
L["Raid Debuffs shows the common raid debuffs (armor, spell and physical damage taken, crit taken, attack power, attack and cast speed, healing taken, Judgements, Hunter's Mark) from anyone."] = "團隊減益效果會顯示任何人施加的常見團隊減益效果（護甲、受到的法術與物理傷害、受到的致命一擊、攻擊強度、攻擊與施法速度、受到的治療、審判、獵人印記）。"
L["Reads the item's own stats; enchants and gems are not counted."] = "讀取物品本身的屬性；附魔與寶石不計入。"
