L["Secondary Spec"] = "次要專精"
L["Selection Color"] = "選取顏色"
L["Selection Color: Custom Color"] = "選取顏色：自訂顏色"
L["SELF COMBAT TEXT"] = "自身戰鬥文字"
L["Self Combat Text"] = "自身戰鬥文字"
L["Sell Junk skips items with no vendor price, equipment set gear and pinned items."] = "販賣垃圾會略過無商店售價的物品、套裝管理員裝備與已釘選的物品。"
L["Shaped"] = "塑形"
L["Shaped Cooldown Swipe"] = "塑形冷卻轉圈"
L["Share Keybind With"] = "共用快捷鍵於"
L["Shift + Click World Markers"] = "Shift + 點擊世界標記"
L["Shift + Left Click a marker icon to use its world marker item, then click the ground. Only markers whose item is in your bags get it; the rest keep Shift + Click to clear the target marker. Shift + Left Click the clear icon presses the server's Reset Markers button."] = "Shift + 左鍵點擊標記圖示以使用其世界標記物品，然後點擊地面。只有物品在背包中的標記才有此功能；其餘標記仍以 Shift + 點擊清除目標標記。Shift + 左鍵點擊清除圖示會按下伺服器的重置標記按鈕。"
L["Show a small coin in the corner of items marked as junk."] = "在標記為垃圾的物品角落顯示小硬幣。"
L["Show at Max Level"] = "滿級時顯示"
L["Show Coin on Junk"] = "在垃圾上顯示硬幣"
L["Show Convert to Raid"] = "顯示轉換為團隊"
L["Show Dividers"] = "顯示分隔線"
L["Show Equipped Item Color"] = "顯示已裝備物品顏色"
L["Show Inspect Enchant Names Instead of Icons"] = "顯示觀察附魔名稱而非圖示"
L["Show Item Icon Name"] = "顯示物品圖示名稱"
L["Show Item ID on Tooltip"] = "浮動提示顯示物品 ID"
L["Show Player Buffs"] = "顯示玩家增益"
L["Show Reinvite"] = "顯示重新邀請"
L["Show Rested XP"] = "顯示休息經驗值"
L["Show Target Name"] = "顯示目標名稱"
L["Show the coin button in the bag header. Click it, then click items to mark or unmark them as junk. Junk goes into its own Junk category, and a Sell Junk button appears next to the coin while a merchant is open."] = "在背包標題列顯示硬幣按鈕。點擊它，然後點擊物品以標記或取消標記為垃圾。垃圾會歸入獨立的垃圾分類，與商人交易時硬幣旁會出現販賣垃圾按鈕。"
L["Shown at max level. Profession bonuses are only checked on your own sheet."] = "滿級時顯示。專業技能加成只會在你自己的角色面板上檢查。"
L["Shows the common raid debuffs from anyone: armor, spell and physical damage taken, crit taken, attack power, attack and cast speed, healing taken, Judgements and Hunter's Mark."] = "顯示任何人施加的常見團隊減益效果：護甲、受到的法術與物理傷害、受到的致命一擊、攻擊強度、攻擊與施法速度、受到的治療、審判與獵人印記。"
L["Shows the Convert to Raid button. In a raid of five or fewer it reads Convert to Party: everyone is removed and invited back to a new party."] = "顯示轉換為團隊按鈕。在五人以下的團隊中會顯示為轉換為小隊：所有人會被移出，並重新邀請至新的小隊。"
L["Shows the debuffs you apply plus the common raid debuffs from anyone."] = "顯示你施加的減益效果，以及任何人施加的常見團隊減益效果。"
L["Shows the Disband button. It always asks before disbanding, but hiding it puts it out of misclick range for good."] = "顯示解散按鈕。解散前一定會先詢問，但隱藏它能徹底避免誤點。"
L["Shows the hovered player's buffs as icons next to the tooltip (up to 16)."] = "在浮動提示旁以圖示顯示滑鼠指向玩家的增益（最多 16 個）。"
L["Shows the overlay, type icon and border colors only for debuffs you can currently dispel."] = "僅對你目前可驅散的減益效果顯示覆蓋層、類型圖示與邊框顏色。"
L["Shows the Reinvite button. It asks first, then removes everyone and invites them back to the same kind of group. Players have to accept the new invite."] = "顯示重新邀請按鈕。會先詢問，然後移出所有人並重新邀請至相同類型的隊伍。玩家必須接受新的邀請。"
L["Shows your damage taken, healing, avoids and combat enter/leave above the player frame instead of Blizzard's combat text, whose other messages are hidden while this is on. Move it in Unlock Mode."] = "在玩家框架上方顯示你受到的傷害、治療、閃避及進入/離開戰鬥，取代暴雪的戰鬥文字；啟用時暴雪的其他戰鬥文字訊息會被隱藏。可在解鎖模式中移動。"
L["Smart Ticks"] = "智慧刻度"
L["Spell IDs in the Breakdown"] = "明細中的法術 ID"
L["Stagger Hits"] = "錯開命中"
L["Stat Hover Highlight"] = "屬性滑鼠移過高亮"
L["Static"] = "靜態"
L["Straight"] = "直線"
L["Style Page Look Menus"] = "樣式頁面外觀選單"
L["Swipe Color"] = "轉圈顏色"
L["Swipe Style"] = "轉圈樣式"
L["Tank Name"] = "坦克名稱"
L["Text Shadow"] = "文字陰影"
L["The [Merfin] Experience Bar (Luxthos) WeakAura: blue to purple gradient, Quest XP Overlay, spark, rested after quest XP and seven texts with level, times and time to level."] = "[Merfin] Experience Bar (Luxthos) WeakAura：藍到紫漸層、任務經驗值覆蓋層、火花、任務經驗值後的休息經驗值，以及七段顯示等級、時間與升級所需時間的文字。"
L["The classic tooltip box around the meter window, with vanilla header buttons and every EllesmereUI meter feature."] = "在統計視窗周圍加上經典浮動提示框，搭配原版標題按鈕與 EllesmereUI 的所有統計功能。"
L["The gap between a nested menu's icons and the entry that opens it."] = "巢狀選單的圖示與開啟它的項目之間的間距。"
L["The rested segment starts where the Quest XP Overlay ends instead of at your current XP."] = "休息區段從任務經驗值覆蓋層結束處開始，而非從你目前的經驗值開始。"
L["The talent group this action menu works in. Outside it the keybind does nothing and the menu is hidden where it is nested."] = "此動作選單作用的天賦組。在其他天賦組時快捷鍵無效，且巢狀所在處的選單會被隱藏。"
L["Third Timer"] = "第三個計時器"
L["This option requires an EllesmereUI Focus frame."] = "此選項需要 EllesmereUI 專注目標框架。"
L["This option requires XP Bar Style EllesmereUI or Luxthos"] = "此選項需要經驗值條樣式為 EllesmereUI 或 Luxthos"
L["Time This Session and XP per Hour carry on through a /reload (a load within five minutes) instead of starting over."] = "本次時段時間與每小時經驗值會在 /reload（五分鐘內重新載入）後延續，而非重新開始。"
L["Timed Buffs"] = "計時增益"
L["Toggle Raid Tools"] = "切換團隊工具"
L["Toggles the Raid Tools panels, in or out of combat.\n\nLeft-click to set a keybind.\nRight-click to unbind."] = "切換團隊工具面板，戰鬥中或戰鬥外皆可。\n\n左鍵點擊以設定快捷鍵。\n右鍵點擊以解除綁定。"
L["Two Windows"] = "兩個視窗"
L["Uninstall & Reload"] = "解除安裝並重新載入"
L["Uninstall EUI"] = "解除安裝 EUI"
L["Up Left"] = "左上"
L["Up Right"] = "右上"
L["Use another action menu's keybind while that menu is not loaded. Both menus must be assigned to different specs."] = "在另一個動作選單未載入時使用其快捷鍵。兩個選單必須指派給不同的專精。"
L["Which buffs enemy nameplates show. Fine-tune it on the Aura Filters page."] = "敵方名條顯示哪些增益。可在光環篩選頁面中微調。"
L["Which ends of the bar show the gryphons."] = "條的哪一端顯示獅鷲。"
L["XP Bar Style"] = "經驗值條樣式"
L["XP color"] = "經驗值顏色"
L["Every module runs on native Wrath APIs. Retail looks and settings were ported wherever the 3.3.5a client supports them, and Retail-only systems were left out. Notes are grouped by module, newest first, and each header shows that module's backport version."] = "所有模組都以巫妖王原生 API 運作。凡 3.3.5a 用戶端支援之處，皆已移植正式版的外觀與設定，正式版專屬的系統則未納入。說明依模組分組、由新到舊排列，每個標題顯示該模組的移植版本。"
L["Icons beside each enemy for every crowd control category they are under or recovering from: green means the next one lasts half as long, yellow a quarter, red immune. A timer shows the 18 second reset."] = "每個敵人旁顯示其正受到或正在恢復的各類控場效果圖示：綠色表示下一次持續時間減半，黃色為四分之一，紅色為免疫。計時器顯示 18 秒的重置時間。"
L["A health bar for each enemy pet under its owner's frame. Left-click targets the pet, right-click sets focus."] = "每個敵方寵物在其主人框架下方各有一條生命條。左鍵點擊選取寵物，右鍵點擊設為專注目標。"
L["Enemy frames for arena1-5 with class colored health, power and cast bars plus a highlight on your target. Left-click targets, right-click sets focus. There is no Retail equivalent."] = "arena1-5 的敵方框架，含職業顏色的生命、能量與施法條，並高亮你的目標。左鍵點擊選取目標，右鍵點擊設為專注目標。正式版沒有對應功能。"
L["The class icon swaps to the highest priority crowd control or immunity with a spiral and timer, and the PvP trinket icon tracks its 2 minute cooldown from the combat log."] = "職業圖示會切換為優先順序最高的控場或免疫效果，並附螺旋與計時器；PvP 飾品圖示會從戰鬥紀錄追蹤其 2 分鐘冷卻。"
L["Bar Texture lists textures from SharedMedia and other addons using LibSharedMedia"] = "條材質會列出來自 SharedMedia 及其他使用 LibSharedMedia 的插件的材質"
L["Enemies beyond your class's 30-40 yard spell range fade to a chosen opacity"] = "超出你職業 30-40 碼法術範圍的敵人會淡出至選定的不透明度"
L["Preview 2 to 5 sample frames in Unlock Mode, while the options page is open, or with /earena test"] = "在解鎖模式中、選項頁面開啟時或使用 /earena test 時，預覽 2 到 5 個範例框架"
L["Frames stay up while an enemy is stealthed or out of sight, dimmed and marked Unseen"] = "敵人潛行或不在視線內時，框架仍會保留，以變暗方式顯示並標記為「未見」"
L["Optionally hides Blizzard's arena frames while these are in use"] = "使用這些框架時，可選擇隱藏暴雪的競技場框架"
L["The Debuff Filter gets Raid Debuffs and Own and Raid Debuffs, with the same raid debuff list as the Unit Frames."] = "減益效果篩選新增「團隊減益效果」與「自己的與團隊減益效果」，團隊減益清單與單位框架相同。"
L["Choose which buffs enemy nameplates show: Timed Buffs, Only Dispellable or Show All, which shows every buff."] = "選擇敵方名條顯示哪些增益：計時增益、僅限可驅散，或顯示全部（顯示所有增益）。"
L["Every nameplate text has an Outline choice under its Size: None, Outline, Thick Outline or Shadow, or keep the module default. Covers names, level, health, Target of Target, cast texts, aura text and friendly names."] = "每個名條文字在其大小下方都有外框選項：無、外框、粗外框或暗影，或沿用模組預設。涵蓋名稱、等級、生命、目標的目標、施法文字、光環文字與友方名稱。"
L["Cast bars now fill every frame instead of stepping with each nameplate refresh. The spark and timer move smoothly too, and the extra work stops when no cast is visible."] = "施法條現在每一畫格都會填充，而非隨每次名條刷新跳動。火花與計時器也會平順移動，且沒有可見施法時會停止額外運算。"
L["Core Text Positions offers all Retail texts: Enemy Name, Level | Name, Target of Target, Health % and Health # with their combined variants. Each text's cog sets its size."] = "核心文字位置提供所有正式版文字：敵方名稱、等級 | 名稱、目標的目標、生命 % 與生命 #，以及其組合變體。每個文字的齒輪可設定其大小。"
L["Health and cast bars offer the EllesmereUI textures (Melli, Atrocity, Fade, Matte and more), as on Retail"] = "生命條與施法條提供 EllesmereUI 材質（Melli、Atrocity、Fade、Matte 等），與正式版相同"
L["Health and cast bar textures include textures from SharedMedia and other addons"] = "生命條與施法條材質包含來自 SharedMedia 及其他插件的材質"
L["Display and Colors show a live preview plate; click any part of it to jump to its setting"] = "顯示與顏色頁面會顯示即時預覽名條；點擊其任一部分即可跳至對應設定"
L["Retail bar size, colors, threat modes, cast colors, target arrows and Execute Pulse Glow"] = "正式版的條大小、顏色、仇恨模式、施法顏色、目標箭頭與斬殺脈動發光"
L["Each slot holds one element; auras, raid marker and classification can also sit below the cast bar"] = "每個欄位放置一個元素；光環、團隊標記與分類也可放在施法條下方"
L["Health # uses Blizzard style abbreviations (1.2K, 12K, 1.2M) with an optional % decimal"] = "生命 # 使用暴雪風格的縮寫（1.2K、12K、1.2M），並可選擇顯示 % 小數"
L["A profile imported from Retail no longer blows the target nameplate up to fill the screen."] = "從正式版匯入的設定檔不再讓目標名條放大到佔滿整個畫面。"
L["Border None now hides only the borders, not the cast bar text, timer, shield and kick mark."] = "邊框設為「無」時現在只會隱藏邊框，不會隱藏施法條文字、計時器、護盾與斷法標記。"
L["The options preview plate no longer disappears after switching tabs or closing the panel."] = "選項預覽名條在切換分頁或關閉面板後不再消失。"
L["The Interrupt on CD cast color now shows while your interrupt recharges, as on Retail, instead of the reverse."] = "「中斷冷卻中」施法顏色現在會在你的斷法技能冷卻時顯示，與正式版相同，而非相反。"
L["Raid and party names each get their own outline: None, Outline, Thick Outline, Shadow, or the Raid Frames font default."] = "團隊與小隊名稱各自擁有外框設定：無、外框、粗外框、暗影，或團隊框架字型預設。"
L["A new Group Layout stacks two raid groups per column, then starts the next column to the right, so a 20-player raid forms a 2x2 block."] = "新的隊伍版面每欄堆疊兩個團隊小組，然後往右開始下一欄，因此 20 人團隊會排成 2x2 區塊。"
L["Ready check icons appear above debuffs and keep each player result for ten seconds after the check finishes."] = "準備確認圖示顯示在減益效果上方，並在確認結束後保留每位玩家的結果十秒。"
L["The debuff displayed in the central Raid Debuff icon is excluded from the regular debuff bar, leaving room for other debuffs."] = "顯示於中央團隊減益圖示的減益效果，不會再出現在一般減益效果列中，為其他減益效果騰出空間。"
L["Raid and party frames dim outside range on Wrath, including in combat. Dim Out of Range and Out of Range Alpha control the fade."] = "在巫妖王中，團隊與小隊框架超出範圍時會變暗，戰鬥中亦然。由「超出範圍時變暗」與「超出範圍透明度」控制淡出。"
L["A large icon in the middle of each frame for important ICC, Ruby Sanctum, Trial of the Crusader, Ulduar and Naxxramas debuffs, highest priority first, with timer, stacks and a dispel colored border. Without a listed debuff it can show a dispellable one instead."] = "每個框架中央有一個大圖示，顯示 ICC、晶紅聖所、十字軍試煉、奧杜亞與納克薩瑪斯的重要減益效果，優先順序最高者在前，附計時器、層數與驅散顏色邊框。沒有列出的減益效果時，可改為顯示可驅散的減益。"
L["Dispel Overlay styles with opacity, a dispel colored Frame Border, Type Icon Position, per-type Dispel Colors and Only Show Dispellable."] = "驅散顏色疊加效果樣式含不透明度、驅散顏色的框架邊框、類型圖示位置、各類型驅散提示顏色，以及僅顯示可驅散的。"
L["Overlay, Real or No Preview. The preview opens while the Raid or Party page is open and closes when you leave it, close the panel or enter combat."] = "覆蓋層、真實或無預覽。預覽會在團隊或小隊頁面開啟時出現，並在你離開頁面、關閉面板或進入戰鬥時關閉。"
L["Enemy casts show as icons on the party or raid member being cast at, with a cast sweep and interruptible border. Party defaults to When Healing; each raid layout has its own mode. Wrath has no spell target, so the victim is the caster's target, and only enemies someone in the group targets are seen"] = "敵方施法會以圖示顯示在被施法的小隊或團隊成員身上，附施法轉圈與可中斷邊框。小隊預設為「治療時」；每種團隊版面各有自己的模式。巫妖王沒有法術目標，因此受害者為施法者的目標，且只會看到隊伍中有人選取的敵人"
L["Damage shields show on the health bar as on Retail: Absorb Style, Opacity, Color, Placement and Show Overshield. Wrath does not report shield amounts, so they are estimated from the combat log"] = "傷害護盾會如正式版般顯示在生命條上：吸收樣式、不透明度、顏色、擺放位置與顯示溢出護盾。巫妖王不會回報護盾數值，因此由戰鬥紀錄估算"
L["Health Bar Texture lists textures from SharedMedia and other addons, also in the aura indicator preview"] = "生命條材質會列出來自 SharedMedia 及其他插件的材質，光環指示器預覽中亦然"
L["25-Player Preview"] = "25 人預覽"
L["The Unlock Mode and options previews open on the 25-player layout instead of 40"] = "解鎖模式與選項預覽改以 25 人版面開啟，而非 40 人"
L["Health color modes, backgrounds, threat, target and hover borders, text and icon placement"] = "生命顏色模式、背景、仇恨、目標與滑鼠移過邊框、文字與圖示擺放"
L["Incoming heals and resurrections from players who use a HealComm addon"] = "來自使用 HealComm 插件的玩家的即將到來治療與復活"
L["Main Tank, Pet and Friendly Boss frames plus Healer Mana text, each with an Unlock Mode mover"] = "主坦克、寵物與友方首領框架，以及治療者法力文字，各有解鎖模式移動器"
L["The Party page has a LAYOUT section with Horizontal Frames"] = "小隊頁面新增版面配置區塊，含水平框架"
L["Ready check icons show a green check for players who accepted and for the one who started the check, instead of a red X when the check ended."] = "準備確認圖示會對已接受的玩家及發起確認者顯示綠色勾號，而非在確認結束時顯示紅色 X。"
L["The party leader icon shows on the leader only instead of on several party members."] = "隊長圖示只會顯示在隊長身上，而非多位小隊成員身上。"
L["Set Focus and Clear Focus in the raid and party frame menu work out of combat without the 'blocked from an action' popup; in combat they are hidden, use a Click Casting Focus binding there."] = "團隊與小隊框架選單中的設為專注目標與清除專注目標，在脫離戰鬥時可正常使用，不會跳出「已被禁止執行動作」的提示；戰鬥中會隱藏，請改用點擊施法的專注目標綁定。"
L["Ready check icons show on raid and party frames again."] = "準備確認圖示再次顯示於團隊與小隊框架上。"
L["Hide Sated / Exhaustion also hides the 81005 Bloodlust lockout debuff."] = "隱藏滿足 / 力竭也會隱藏 81005 嗜血冷卻減益效果。"
L["Pet frames no longer throw a SecureTemplates strupper error when they first appear."] = "寵物框架首次出現時不再拋出 SecureTemplates strupper 錯誤。"
L["The Buffs/Debuffs editor's Add New menu no longer closes on the first click."] = "增益/減益效果編輯器的「新增」選單不再於第一次點擊時關閉。"
L["Element Options for raid and party frames now open the matching settings."] = "團隊與小隊框架的元素選項現在會開啟對應的設定。"
L["Profile strings exported from Retail EllesmereUI import everything this client supports: each module keeps its current settings and takes the Retail values it understands. Retail-only modules, spec setups and Cooldown Manager spells are skipped, and chat reports how many settings came in."] = "從正式版 EllesmereUI 匯出的設定檔字串，會匯入此用戶端支援的所有內容：每個模組保留目前設定，並套用其能理解的正式版數值。正式版專屬模組、專精設定與冷卻管理器法術會被略過，聊天視窗會回報匯入了多少設定。"
L["A button on Global Settings puts back the game settings EUI changed (nameplate, minimap, chat and tooltip options, chat font sizes and keys Quickdraw took), then turns EUI off for this character and reloads. Your profiles are kept."] = "全域設定中的按鈕可還原 EUI 變更過的遊戲設定（名條、小地圖、聊天與浮動提示選項、聊天字型大小及快抽選單佔用的按鍵），然後為此角色關閉 EUI 並重新載入。你的設定檔會保留。"
L["A drawn cooldown sweep for modules that want round or colored swipes; the Wrath client's own swipe is always a dark square. Cooldown Manager uses it first."] = "為需要圓形或彩色轉圈的模組提供繪製的冷卻轉圈；巫妖王用戶端本身的轉圈一律是深色方形。冷卻管理器率先使用。"
L["When a guild or group member runs a newer EllesmereUI release, chat tells you once per session. Type /euiupdate for the download link. Wrath has no internet access, so the news comes from other EUI users."] = "當公會或隊伍成員使用較新版本的 EllesmereUI 時，聊天視窗每個登入時段會通知你一次。輸入 /euiupdate 取得下載連結。巫妖王無法連上網路，因此消息來自其他 EUI 使用者。"
L["The Locales addon provides community translations for all original Wrath client languages, with English fallback and Lua 5.1 formatting."] = "Locales 插件為所有原始巫妖王用戶端語言提供社群翻譯，並以英文作為備援，採用 Lua 5.1 格式。"
L["The collapsed menu displays the original Ellesmere E logo with the UI accent color and a working close icon on the Wrath client."] = "在巫妖王用戶端上，收合的選單會顯示原版 Ellesmere E 標誌，套用介面強調色，並有可用的關閉圖示。"
L["Fonts, bar textures and sounds that other addons register with LibSharedMedia appear in the EllesmereUI menus, including ones registered after login."] = "其他插件透過 LibSharedMedia 註冊的字型、條材質與音效會出現在 EllesmereUI 選單中，包含登入後才註冊的項目。"
L["A shared outline picker for individual texts: None, Outline, Thick Outline or Shadow, with Module Default following the Fonts page. Text keeps its color when you switch."] = "供個別文字使用的共用外框選擇器：無、外框、粗外框或暗影，模組預設則沿用字型頁面。切換時文字保留其顏色。"
L["The Incompatible Addon popup can disable the other addon or the affected EllesmereUI module and reload. Okay and Don't show again work as before."] = "不相容插件提示可停用另一個插件或受影響的 EllesmereUI 模組並重新載入。「確定」與「不再顯示」功能與以往相同。"
L["Per-spec setting groups with automatic capture and their own Unlock Mode layouts, plus conditional overrides for dungeons, raids, arenas, battlegrounds, solo play and out of combat."] = "各專精的設定群組，可自動擷取並擁有各自的解鎖模式版面，另有針對地城、團隊、競技場、戰場、單人遊玩與脫離戰鬥的條件覆寫。"
L["The Esc menu has EllesmereUI and EUI Unlock Mode buttons, shown by default. Both follow the EUI Buttons setting in Global Settings."] = "Esc 選單有 EllesmereUI 與 EUI 解鎖模式按鈕，預設顯示。兩者皆依循全域設定中的 EUI 按鈕設定。"
L["With Show Spell ID on Tooltip on, item tooltips add the item ID and icon file name. Each line has its own toggle"] = "開啟「在提示資訊顯示法術 ID」時，物品浮動提示會加上物品 ID 與圖示檔名。每一行都有各自的開關"
L["Raid and Unit Frames read absorb shields from a shared estimate: rank base value plus your own spell power, minus what each shield absorbs in the combat log. Clients with a native absorb API use it directly"] = "團隊框架與單位框架從共用估算值讀取吸收護盾：等級基礎值加上你自己的法術能量，減去戰鬥紀錄中每個護盾吸收的量。具有原生吸收 API 的用戶端則直接使用該 API"
L["Arena Frames joins the sidebar, first-use list, profiles, spec overrides, module fonts and search"] = "競技場框架加入側欄、首次使用清單、設定檔、專精覆寫、模組字型與搜尋"
L["Profile strings and shared exports work again"] = "設定檔字串與共用匯出再次正常運作"
L["An ice blue options theme; Match Accent to Theme follows each theme's palette"] = "冰藍色選項主題；強調色符合主題會依循各主題的色盤"
L["Lights, beams, music and spin on boss kills, arena and battleground wins, Bloodlust/Heroism and level ups"] = "擊殺首領、贏得競技場與戰場、嗜血/英雄氣概及升級時的燈光、光束、音樂與旋轉效果"
L["Show Spell ID on Tooltip covers spells, action buttons, auras and chat links (off by default)"] = "在提示資訊顯示法術 ID 涵蓋法術、動作按鈕、光環與聊天連結（預設關閉）"
L["The options sidebar shows the combined memory used by all loaded EllesmereUI addons"] = "選項側欄顯示所有已載入 EllesmereUI 插件的合計記憶體用量"
L["The sidebar sync button opens its profile list again instead of erroring when you have more than one profile."] = "當你有多個設定檔時，側欄同步按鈕再次開啟其設定檔清單，不再發生錯誤。"
L["Retail profile strings bring their element positions: action, XP and menu bars, CDM bars, raid and party frames, chat, damage meter windows, QoL displays, resource bars and the fixed tooltip land where the creator placed them."] = "正式版設定檔字串會帶入元素位置：快捷列、經驗條與選單列、CDM 條、團隊與小隊框架、聊天、傷害統計視窗、體驗優化顯示、資源條與固定浮動提示，都會落在建立者擺放的位置。"
L["Nameplates-only Retail profile strings are recognised as Retail; bar width and height, cast bar height and color, name size and aura sizes carry over."] = "僅含名條的正式版設定檔字串會被辨識為正式版；條的寬度與高度、施法條高度與顏色、名稱大小與光環大小都會沿用。"
L["Unlock Mode: the top bar toggle icons and labels are brighter, so they no longer read dark grey on the banner."] = "解鎖模式：頂部列的切換圖示與標籤更亮，不再在橫幅上顯示為深灰色。"
L["Set Focus and Clear Focus in right-click menus from EUI frames go through a secure button out of combat instead of being blocked; in combat they are hidden."] = "EUI 框架右鍵選單中的設為專注目標與清除專注目標，在脫離戰鬥時透過安全按鈕執行，不再被禁止；戰鬥中會隱藏。"
L["Unlock Mode: the arrow keys move the selected element 1 pixel again (hold Shift for 100)."] = "解鎖模式：方向鍵再次可將選取的元素移動 1 像素（按住 Shift 為 100）。"
L["Works alongside !!!ClassicAPI: its clipping and mask functions are no longer used on EUI frames, so animated glows and the options panel stop erroring."] = "可與 !!!ClassicAPI 並用：EUI 框架不再使用其裁切與遮罩函式，因此動畫發光與選項面板不再發生錯誤。"
L["Opening the options no longer errors with \"attempt to index local 'mask'\" on clients where another addon adds an empty mask function."] = "在其他插件加入空白遮罩函式的用戶端上，開啟選項不再出現 \"attempt to index local 'mask'\" 錯誤。"
L["The profile Import and Export boxes no longer error with \"attempt to call method 'GetNumLines'\" and scroll to fit long strings."] = "設定檔匯入與匯出框不再出現 \"attempt to call method 'GetNumLines'\" 錯誤，並可捲動以容納長字串。"
L["The collapsed menu shows the Ellesmere E logo again instead of a plain black circle."] = "收合的選單再次顯示 Ellesmere E 標誌，而非一個純黑色圓圈。"
L["Action button tooltips show the real spell ID instead of the spellbook slot."] = "動作按鈕的浮動提示顯示真正的法術 ID，而非法術書欄位編號。"
L["Fixed an \"attempt to call global 'issecretvalue'\" error from Cooldown Manager glows before the options panel was first opened."] = "修正首次開啟選項面板前，冷卻管理器發光出現的 \"attempt to call global 'issecretvalue'\" 錯誤。"
L["Unlock Mode widget tooltips use Wrath-compatible alpha fades, fixing the SetFromAlpha error on Grow Right."] = "解鎖模式小工具的浮動提示改用相容巫妖王的透明度淡出，修正「向右增長」的 SetFromAlpha 錯誤。"
L["The options search results list has a fully opaque background with its results drawn above it, so sidebar and page text no longer bleeds into the results."] = "選項搜尋結果清單有完全不透明的背景，結果繪製於其上，因此側欄與頁面文字不再滲入結果中。"
L["Unlock Mode no longer errors on SetMaxLines when it first opens, so element movers appear again."] = "解鎖模式首次開啟時不再出現 SetMaxLines 錯誤，元素移動器再次顯示。"
L["The Patch Notes reminder dot now lights after each backport update."] = "每次移植版更新後，更新說明提醒點現在會亮起。"
L["The options search results now draw above the sidebar and page instead of behind them."] = "選項搜尋結果現在繪製在側欄與頁面之上，而非其後方。"
L["The Unlock Mode right-click menu no longer closes right after opening when many elements are on screen."] = "畫面上有許多元素時，解鎖模式右鍵選單不再於開啟後立即關閉。"
L["Opening the Raid Frames options no longer causes a stack overflow in Settings Overrides."] = "開啟團隊框架選項時，設定覆寫不再造成堆疊溢位。"
L["Unlock Mode art, options page icons and the Unlock Mode top bar are now visible and readable."] = "解鎖模式美術、選項頁面圖示與解鎖模式頂部列現在都清晰可見、易於閱讀。"
L["The addon list shows clean module names, grouped under EllesmereUI in addon managers."] = "插件清單顯示簡潔的模組名稱，並在插件管理器中歸類於 EllesmereUI 底下。"
L["Search Features and Search Module Settings accept typing again."] = "搜尋功能與搜尋模組設定再次可以輸入文字。"
L["Clients whose atlas lookup errors on unknown names (such as custom 3.3.5 clients with Retail UI ports) no longer stop EllesmereUI files from loading."] = "在查詢未知名稱的 atlas 時會出錯的用戶端（例如移植了正式版介面的自訂 3.3.5 用戶端）上，EllesmereUI 檔案不再停止載入。"
L["Like Retail 9.4, the DataBars page opens with a bar selector at the top: rename or delete a bar right in its menu, or pick + Create New DataBar. + New Bar shows the four starter templates as cards, and with no bars yet the page shows them as a card grid."] = "如同正式版 9.4，資訊列頁面頂端有條選擇器：可直接在其選單中重新命名或刪除條，或選擇「+ 建立新資訊列」。「+ 新增條」會以卡片顯示四種起始範本；尚未有任何條時，頁面會以卡片網格顯示它們。"
L["Like Retail 9.4, the options window has a Window Scale slider in its top corner that resizes it in smooth 5% steps; the mouse wheel over it, or Shift + mouse wheel anywhere on the window, works too. The credit to Ellesmere now sits under the close button."] = "如同正式版 9.4，選項視窗角落有視窗縮放滑桿，可以 5% 為一階平順調整大小；在滑桿上滾動滑鼠滾輪，或在視窗任何地方按住 Shift 滾動滾輪也可以。對 Ellesmere 的致謝現在位於關閉按鈕下方。"
L["Global Settings opens with Reset ALL EUI Addon Settings and Uninstall EUI side by side, like Retail 9.4. Reset ALL now asks you to type Confirm. Optimize My FPS and Graphics is gone: the graphics settings it changed do not exist on this client."] = "全域設定開啟時，「重設所有 EUI 插件設定」與「解除安裝 EUI」並排顯示，如同正式版 9.4。「重設所有」現在需要你輸入 Confirm。「最佳化我的 FPS 與畫面」已移除：它所變更的圖形設定在此用戶端不存在。"
L["Like Retail 9.4, each look card on the Style page has a menu of the modules using it: tick modules under another look, then press Apply Styles to switch them all with one reload. The menus list only looks this client can draw: Cooldown Manager, Minimap and Damage Meters offer EllesmereUI and Classic WoW UI, Player Aura Bars is gone, and Apply to All skips modules without that look."] = "如同正式版 9.4，樣式頁面上每張外觀卡片都有使用該外觀的模組選單：勾選另一個外觀下的模組，然後按「套用樣式」，只需重新載入一次即可全部切換。選單只列出此用戶端能繪製的外觀：冷卻管理器、小地圖與傷害統計提供 EllesmereUI 與經典 WoW 介面，玩家光環條已移除，「套用至所有」會略過沒有該外觀的模組。"
L["The import page can update your current profile instead of making a new one: tick Import into current profile and the string's selected modules (for example only Nameplates) replace their settings there while the rest of the profile stays."] = "匯入頁面可更新你目前的設定檔，而非建立新設定檔：勾選「匯入至目前設定檔」，字串中選取的模組（例如僅名條）會取代該設定檔中的對應設定，其餘部分保持不變。"
L["The EUI Staff page opens with thanks to Ellesmere and the port staff card with a GitHub link to the releases. The header line crediting Ellesmere opens it."] = "EUI 團隊頁面開頭是對 Ellesmere 的致謝，以及附有 GitHub 發行版本連結的移植團隊卡片。點擊致謝 Ellesmere 的標題行即可開啟。"
L["Custom spell reminders, visibility and sounds are saved separately for each character, independently of shared profiles."] = "自訂法術提醒、可見性與音效會依角色分別儲存，與共用設定檔無關。"
L["Optional achievement, trade and guild recruitment filters, plus your own blocked words and phrases."] = "可選的成就、交易與公會招募過濾，以及你自己封鎖的字詞與片語。"
L["Configure repeat timing, sender matching and chat scopes from the new Spam Filter page."] = "在新的垃圾訊息過濾頁面設定重複時間、發送者比對與聊天範圍。"
L["Outline menus in the Nameplates and Unit Frames text cogs, and Zone Text Outline in Quality of Life. The Unit Frames preview shows each text's outline."] = "名條與單位框架文字齒輪中的外框選單，以及體驗優化中的區域文字外框。單位框架預覽會顯示每個文字的外框。"
L["New PETS and DIMINISHING RETURNS sections, plus Fade Out of Range and its opacity under Target and Visibility."] = "新增寵物與遞減效應區塊，並在目標與可見性下新增超出範圍時淡出及其不透明度。"
L["Announce Interrupts and Accept Invites from Friends & Guild in the GROUP section, and a Disband Group button on Raid Tools."] = "隊伍區塊新增通報斷法與接受好友與公會的邀請，團隊工具新增解散群組按鈕。"
L["Bar Display, Menu, Bags & XP Bars and Bar Animations, with a live preview of the selected bar. Click an icon, keybind or count to jump to its setting."] = "條顯示、選單、背包與經驗條及條動畫，附選取條的即時預覽。點擊圖示、快捷鍵或數量即可跳至其設定。"
L["The Raid and Party pages gain the Retail DISPELS section and a Preview Mode (Real, Overlay or No Preview) at the top."] = "團隊與小隊頁面頂端新增正式版的驅散區塊與預覽模式（真實、覆蓋層或無預覽）。"
L["Party and Raid pages gain a TARGETED SPELLS section: mode, preview, icon size, maximum icons, position, growth, offsets, cast swipe, cast timer and interruptible colors."] = "小隊與團隊頁面新增被指向法術區塊：模式、預覽、圖示大小、最大圖示數、位置、增長方向、偏移、施法轉圈、施法計時器與可中斷顏色。"
L["Raid Frames (Party and Raid) and Unit Frames (player, target, focus) gain an ABSORBS section for the estimated shields, with a shield in the Unit Frames preview."] = "團隊框架（小隊與團隊）與單位框架（玩家、目標、專注目標）新增吸收區塊以顯示估算護盾，單位框架預覽中也會顯示護盾。"
L["CDM Bars now opens with Retail's bar dropdown (rename or delete custom bars, add Cooldowns, Utility, Buff or FocusKick bars) and the selected bar's icons: drag to reorder, click an icon to edit it, middle-click to remove it, and use + to add spells or buffs."] = "CDM 條現在開啟時顯示正式版的條下拉選單（重新命名或刪除自訂條，新增冷卻、輔助、增益或焦點打斷條）以及所選條的圖示：拖曳以重新排序，點擊圖示以編輯，中鍵點擊以移除，並用 + 新增法術或增益。"
L["Hide server announcements such as \"Name the level 11 Gnome Warrior has been slain by ... in Westfall\", optionally keeping deaths from a chosen level up visible."] = "隱藏伺服器公告，例如 \"Name the level 11 Gnome Warrior has been slain by ... in Westfall\"，並可選擇保留達到指定等級以上的死亡訊息。"
L["The FocusKick Cast Sound and the Chat sounds list EllesmereUI and SharedMedia sounds, and the Textures page links Damage Meters to its per-window Bar Texture"] = "焦點打斷施法音效與聊天音效會列出 EllesmereUI 與 SharedMedia 音效，材質頁面會將傷害統計連結至各視窗的條材質"
L["New dropdown at the top of Icons, with a link to apply it to every bar. The preview shows the shape."] = "圖示區塊頂端的新下拉選單，附有套用至每個條的連結。預覽會顯示形狀。"
L["Boss Debuff Icon, Icon Size, Icon Offset Y and Show Dispellable When No Boss Debuff under Dispels"] = "驅散下的首領減益圖示、圖示大小、圖示 Y 偏移與無首領減益時顯示可驅散效果"
L["General, Layout, Health and Power, Text, Icons, Cast Bar and Target and Visibility sections"] = "一般、版面配置、生命與能量、文字、圖示、施法條，以及目標與可見性區塊"
L["Display, Extras and Wrath Inventory settings, including Delete Saved Character"] = "顯示、額外與巫妖王背包設定，包含刪除已儲存角色"
L["Class icon themes, class colored names, borders, accent colors, faction banners and invite auto-accept"] = "職業圖示主題、職業顏色名稱、邊框、強調色、陣營旗幟與自動接受邀請"
L["Display, Colors, General and Aura Filters with inline color swatches and cog menus"] = "顯示、顏色、一般與光環篩選，附內嵌顏色樣本與齒輪選單"
L["Quick Loot, Auto-Fill Delete Confirmation, Auto Repair and Auto Sell Junk in the Retail layout"] = "正式版版面的快速拾取、自動填入刪除確認、自動修理與自動販賣垃圾"
L["Display, Colors and Extras sections with inline swatches and auto accept and turn-in cogs"] = "顯示、顏色與額外區塊，附內嵌顏色樣本以及自動接受與交付任務的齒輪"
L["Wrath spell icons, real cast times and the same faction and portrait art as the live frames"] = "巫妖王法術圖示、真實施法時間，以及與實際框架相同的陣營與頭像美術"
L["The Active Profile dropdown shows the rename, delete and keybind icons on each profile again."] = "使用中設定檔下拉選單再次在每個設定檔上顯示重新命名、刪除與快捷鍵圖示。"
L["Dropdowns open again with !!!ClassicAPI installed; its clipping function no longer moves the menus into an empty scroll frame."] = "安裝 !!!ClassicAPI 時下拉選單再次可以開啟；其裁切函式不再將選單移入空白的捲動框架。"
L["Resetting Global Settings no longer stops partway with an error and reloads the UI again."] = "重設全域設定不再於中途因錯誤停止並再次重新載入介面。"
L["Options that do nothing on the Wrath client are hidden: image sharpening, Lag Tolerance, Combat Text Size, Swiftmend dim, Slug outline, class resource dark mode and colors, Retail-only class and power colors, and cursor ring textures."] = "在巫妖王用戶端上無作用的選項已隱藏：影像銳利化、延遲容許值、戰鬥文字大小、迅癒變暗、Slug 外框、職業資源暗色模式與顏色、正式版專屬的職業與能量顏色，以及游標光圈材質。"
L["Global Settings no longer shows the Gamepad page, which has nothing to control on the Wrath client."] = "全域設定不再顯示遊戲手把頁面，該頁面在巫妖王用戶端上沒有可控制的項目。"
L["Max Camera Distance saves and keeps its value instead of resetting to 1.0, and goes up to 4 like the Wrath client allows."] = "最大鏡頭距離會儲存並保留其數值，不再重設為 1.0，且最高可達 4，與巫妖王用戶端允許的範圍相同。"
L["CDM Bars and Tracking Bars open without an \"attempt to call field 'disabled'\" error, and nine toggles show their tooltips again."] = "CDM 條與追蹤條開啟時不再出現 \"attempt to call field 'disabled'\" 錯誤，九個開關再次顯示其浮動提示。"
L["Chat > Spam Filter: the chat type settings stay usable when only the trade or recruitment filter is on, and the tooltips explain what each one covers."] = "聊天 > 垃圾訊息過濾：只開啟交易或招募過濾時，聊天類型設定仍可使用，且浮動提示會說明每個設定涵蓋的範圍。"
L["Opening the options no longer makes later Blizzard actions risk being blocked in EllesmereUI's name."] = "開啟選項後，之後的暴雪動作不再有以 EllesmereUI 名義被禁止的風險。"
L["Checklist menus such as Visibility tick and untick their boxes as soon as they are clicked, even when the module's live update runs into a problem, instead of only after closing and reopening the menu."] = "可見性等勾選清單選單，在點擊時會立即勾選或取消勾選，即使模組的即時更新遇到問題也一樣，而不必關閉再重新開啟選單。"
L["Dropdown lists, checklists and other option popups draw their items above their own background, on a solid background, instead of showing faded items with the page bleeding through."] = "下拉清單、勾選清單及其他選項彈出視窗，會在實心背景上將項目繪製於自身背景之上，而非顯示褪色的項目並透出頁面。"
L["The Style page now keeps the Unit Frames health colors per look, so switching between Classic WoW UI and the EllesmereUI look keeps each one's colors."] = "樣式頁面現在會依外觀分別保留單位框架的生命顏色，因此在經典 WoW 介面與 EllesmereUI 外觀之間切換時，各自的顏色都會保留。"
L["The Unit Frames preview and power color swatches show the original game power colors under Classic WoW UI."] = "在經典 WoW 介面下，單位框架預覽與能量顏色樣本會顯示原始遊戲的能量顏色。"
L["Each Core Text Position row, Spell Name, Cast Timer and Friendly Names now has its own gear for the outline instead of hiding it in the size popup."] = "每一列核心文字位置、法術名稱、施法計時器與友方名稱現在都有各自的外框齒輪，而非藏在大小彈出視窗中。"
L["Pressing Esc to close Blizzard windows no longer shows \"EllesmereUIOptions has been blocked from an action\"."] = "按 Esc 關閉暴雪視窗時，不再顯示 \"EllesmereUIOptions has been blocked from an action\"。"
L["Combat damage, healing, periodic and pet damage toggles use Wrath's own combat text settings."] = "戰鬥傷害、治療、週期性與寵物傷害開關使用巫妖王本身的戰鬥文字設定。"
L["Hidden option widgets no longer take keyboard focus after other windows close with Escape."] = "其他視窗以 Esc 關閉後，隱藏的選項小工具不再取得鍵盤焦點。"
L["Dragging or typing in a slider no longer errors."] = "拖曳滑桿或在滑桿中輸入不再出錯。"
L["The settings panel opens on clients whose atlas lookup errors on unknown names, instead of failing with an 'NS' error."] = "在查詢未知名稱的 atlas 時會出錯的用戶端上，設定面板可以開啟，不再因 'NS' 錯誤而失敗。"
L["Displays has a ZONE TEXT section with Move Zone Text."] = "顯示頁面新增區域文字區塊，含移動區域文字。"
L["Raid Tools no longer has a BOSS MOD BARS section: AbilityTimeline's Sources options hide DBM and BigWigs bars."] = "團隊工具不再有首領模組計時條區塊：AbilityTimeline 的 Sources 選項可隱藏 DBM 與 BigWigs 計時條。"
L["The Retail raid panel: show it never, in raids, in any group or always, as a resizable Compact Band, one or two windows, or only one part. It can start as a small icon, opens and closes with a keybind even in combat, and has three pull timers, Convert and Disband. Reinvite removes everyone and invites them back to the same kind of group, and Convert to Party rebuilds a raid of five or fewer as a party the same way. Shift + Left Click a marker to place its world marker when the marker item is in your bags, or Shift + Left Click the clear icon to reset world markers. In a raid it only shows for the leader and assistants."] = "正式版團隊面板：可設為從不顯示、在團隊中、在任何隊伍中或總是顯示，形式可為可調整大小的精簡橫列、一個或兩個視窗，或只顯示其中一部分。它可以小圖示開始，即使在戰鬥中也可用快捷鍵開關，並有三個開怪倒數、轉換與解散。重新邀請會移出所有人並重新邀請至相同類型的隊伍，轉換為小隊則以相同方式將五人以下的團隊重組為小隊。當標記物品在背包中時，Shift + 左鍵點擊標記可放置其世界標記，或 Shift + 左鍵點擊清除圖示以重置世界標記。在團隊中只對隊長與助理顯示。"
L["One key casts Misdirection or Tricks of the Trade on your focus, the tank (typed name, Main Tank or tank role), your friendly target or your pet. An icon shows who it will go to, the buff timer and the cooldown. Bind it in Key Bindings."] = "一個按鍵即可對你的專注目標、坦克（輸入的名稱、主坦克或坦克職責）、你的友方目標或你的寵物施放誤導或偷天換日。圖示會顯示施放對象、增益計時器與冷卻。請在按鍵設定中綁定。"
L["Damage taken, healing, avoids and entering or leaving combat scroll above the player frame instead of Blizzard's combat text, with Straight, Fountain or Static animations, colors per type and a mover in Unlock Mode."] = "受到的傷害、治療、閃避及進入或離開戰鬥，會在玩家框架上方捲動顯示，取代暴雪的戰鬥文字，提供直線、噴泉或靜態動畫、各類型顏色，以及解鎖模式中的移動器。"
L["Picks an NPC's only dialog option for you. Hold Shift to skip it; instances and NPCs with quests to take or turn in are left alone. Its cog can also skip past low level quests."] = "自動為你選擇 NPC 唯一的對話選項。按住 Shift 可略過；副本及有任務可接或可交的 NPC 不受影響。其齒輪也可略過低等級任務。"
L["An arrow next to the To box lists your alts on this realm and faction, guild members and the last names you mailed. Click a name to fill it in."] = "收件人欄位旁的箭頭會列出你在此伺服器與陣營的分身、公會成員及最近寄信的對象。點擊名稱即可填入。"
L["Pick None, Outline, Thick Outline or Shadow for the zone, sub-zone and PvP text shown when entering an area. Blizzard Default keeps the game's own font."] = "為進入區域時顯示的區域、子區域與 PvP 文字選擇無、外框、粗外框或暗影。暴雪預設保留遊戲本身的字型。"
L["Posts the spell you or your pet interrupted, with a spell link, to Say, Emote, Party or Raid. Party and Raid switch to the battleground channel inside battlegrounds."] = "將你或你的寵物打斷的法術，附法術連結發布至說、表情、小隊或團隊頻道。在戰場內，小隊與團隊會切換為戰場頻道。"
L["Group invites from your friends list and guildmates are accepted automatically, unless you are already grouped or queued in the Dungeon Finder."] = "自動接受來自好友名單與公會成員的隊伍邀請，除非你已在隊伍中或正在地城搜尋器佇列中。"
L["A Disband button on Raid Tools removes everyone from your raid or party after a confirmation. Leader only, never in combat."] = "團隊工具上的解散按鈕會在確認後將所有人移出你的團隊或小隊。僅限隊長，戰鬥中無法使用。"
L["Loots everything instantly even with Blizzard's Auto Loot off; hold Shift to see the loot window. Locked slots such as group rolls and master loot are skipped."] = "即使關閉暴雪的自動拾取，也會立即拾取所有物品；按住 Shift 可查看拾取視窗。隊伍擲骰與隊長分配等鎖定的欄位會被略過。"
L["FPS and latency, secondary stats, durability warning, combat and death alerts, a crosshair and a new target distance text, all movable in Unlock Mode."] = "FPS 與延遲、次要屬性、耐久度警告、戰鬥與死亡警示、準星，以及新的目標距離文字，全部都可在解鎖模式中移動。"
L["The FPS counter's new default Text Color, Quality, turns FPS and each latency value green, yellow or red (60/30 fps, 100/250 ms). Custom and Class Color remain available."] = "FPS 計數器新的預設文字顏色「品質」會將 FPS 與各延遲值顯示為綠色、黃色或紅色（60/30 fps，100/250 ms）。仍可使用自訂與職業顏色。"
L["Alert sounds from SharedMedia packs that load after Quality of Life play too"] = "在體驗優化之後才載入的 SharedMedia 套件中的警示音效也能播放"
L["An Open All button takes items and gold one letter at a time, skipping COD and GM mail"] = "「全部開啟」按鈕會逐封取出物品與金錢，略過貨到付款與 GM 信件"
L["With Send Mail open, Shift-click a bag item to attach it and matching items"] = "開啟寄信時，Shift 點擊背包物品即可附加該物品及相符的物品"
L["Opens lootable containers one at a time out of combat (off by default)"] = "脫離戰鬥時逐一開啟可拾取的容器（預設關閉）"
L["A Train All button beside Train shows how many spells are available and the total cost"] = "「學習」旁的「全部學習」按鈕會顯示可學習的法術數量與總花費"
L["Pull timer length, DBM/BigWigs broadcast and a chat countdown"] = "開怪倒數長度、DBM/BigWigs 廣播與聊天倒數"
L["Raid Tools keeps its size after importing a Retail profile."] = "匯入正式版設定檔後，團隊工具會保留其大小。"
L["Shift-click mail attach no longer replaces the bag item click handler, so bag clicks stay free of taint."] = "Shift 點擊附加信件不再取代背包物品的點擊處理函式，因此背包點擊不會受到汙染。"
L["Hiding DBM and BigWigs bars while AbilityTimeline is active moved to AbilityTimeline itself, as on Retail: Hide DBM bars and Hide BigWigs bars on its Sources page. The Raid Tools option is gone."] = "在 AbilityTimeline 啟用時隱藏 DBM 與 BigWigs 計時條的功能已移至 AbilityTimeline 本身，與正式版相同：在其 Sources 頁面的 Hide DBM bars 與 Hide BigWigs bars。團隊工具中的選項已移除。"
L["Logging out, exiting, releasing spirit and other Blizzard confirmation popups no longer trigger the \"EllesmereUIQoL has been blocked from an action only available to the Blizzard UI\" message."] = "登出、離開遊戲、釋放靈魂及其他暴雪確認彈出視窗不再觸發 \"EllesmereUIQoL has been blocked from an action only available to the Blizzard UI\" 訊息。"
L["The zone name no longer appears in the middle of the screen at small UI scales. It now sits fixed at the top (X 9 / Y 322 from screen center), with no Unlock Mode mover."] = "在較小的介面縮放下，區域名稱不再出現在畫面中央。現在固定於頂端（距畫面中心 X 9 / Y 322），沒有解鎖模式移動器。"
L["Show Player Buffs puts the hovered player's buffs as icons beside the tooltip, with position, size, icons per row and offsets."] = "顯示玩家增益會在浮動提示旁以圖示顯示滑鼠指向玩家的增益，可設定位置、大小、每列圖示數與偏移。"
L["Hovering a stat in the character sheet sidebar glows the equipped items that give it."] = "滑鼠移過角色資訊側欄中的屬性時，提供該屬性的已裝備物品會發光。"
L["Inspect Enchants and Missing Enhancements"] = "觀察附魔與缺少的強化"
L["Inspect enchants show as an icon with the name on hover, or as names tinted by item quality, in their own size. At max level, red badges flag missing enchants, empty sockets and a missing belt buckle, as on your character sheet."] = "觀察附魔會以圖示顯示並在滑鼠移過時顯示名稱，或以依物品品質著色的名稱顯示，大小可獨立設定。滿級時，紅色標記會標出缺少的附魔、空插槽與缺少的腰帶扣環，與你的角色資訊相同。"
L["Saving an equipment set rebuilds the native icon picker even when already open, preventing the PaperDollFrame nil comparison error."] = "儲存套裝時，即使原生圖示選擇器已開啟也會重建它，避免 PaperDollFrame nil 比較錯誤。"
L["Need, Greed, Disenchant and Pass buttons on loot rolls count what the rest of the group picked. Hover a button to see who, in class colors."] = "拾取擲骰的需求、貪婪、分解與放棄按鈕會統計隊伍其他成員的選擇。滑鼠移過按鈕可查看是誰，以職業顏色顯示。"
L["Player tooltips show GearScore in the GearScoreLite colors, using its formula when it is loaded. GearScoreLite's own line is kept when its option is on."] = "玩家浮動提示以 GearScoreLite 的顏色顯示 GearScore，載入 GearScoreLite 時會使用其公式。開啟 GearScoreLite 的選項時會保留其本身的那一行。"
L["Enchants and gems on every slot, lowest durability, model rotate, pan and zoom, reorderable stat sections and a socket strip that fills sockets from your bags."] = "每個欄位的附魔與寶石、最低耐久度、模型旋轉、平移與縮放、可重新排序的屬性區塊，以及從背包填入插槽的插槽列。"
L["Class colored names and health bar, guild rank, target, item level and a cursor or fixed anchor"] = "職業顏色名稱與生命條、公會階級、目標、物品等級，以及游標或固定錨點"
L["Item levels on inspect, docking beside the character window and a merchant list mode"] = "觀察時的物品等級、停靠在角色視窗旁，以及商人清單模式"
L["Resurrect accept glow and a Dungeon Ready countdown bar"] = "復活接受發光與地城已就緒倒數條"
L["The server's Collections and Wardrobe & Transmog windows join the window skins"] = "伺服器的收藏與衣櫥與塑形視窗加入視窗外觀"
L["Barber Shop, PvP and battlemasters, Arena Registrar, battleground score, minimap and capture bar, Help and GM tickets, GM chat status, breath and fatigue timers, stopwatch, raid pullouts, debug tools and Ace3 config windows"] = "理髮店、PvP 與戰場軍官、競技場登記員、戰場計分板、小地圖與佔領進度條、說明與 GM 回報單、GM 聊天狀態、呼吸與疲勞計時器、碼錶、團隊拉出框、除錯工具及 Ace3 設定視窗"
L["Ready checks no longer leave an empty black panel for the leader or after you answer."] = "準備確認不再為隊長或在你回應後留下空白的黑色面板。"
L["The character sheet Titles tab lists your known titles again; click one to wear it."] = "角色資訊的頭銜分頁再次列出你已獲得的頭銜；點擊即可使用。"
L["The Guild Message Of The Day popup (and other wide text popups) no longer covers its title and buttons with the input box."] = "公會今日訊息彈出視窗（及其他寬文字彈出視窗）的輸入框不再遮住其標題與按鈕。"
L["The Achievements window no longer darkens the achievement list behind its border."] = "成就視窗不再讓邊框後方的成就清單變暗。"
L["The AddOn List window skin toggle only shows when the client has an AddOn List window."] = "插件清單視窗外觀開關只會在用戶端有插件清單視窗時顯示。"
L["Send Mail shows the To, Subject and message boxes again, and the typing cursor stays visible in skinned edit boxes."] = "寄信再次顯示收件人、主旨與內文框，且套用外觀的輸入框中游標會保持可見。"
L["The fixed tooltip anchor no longer snaps back to its saved spot while you drag it in Unlock Mode."] = "在解鎖模式中拖曳固定浮動提示錨點時，不再彈回其儲存的位置。"
L["Auction House: panels and tabs added by Auctionator and other auction addons keep their own look and layout, and the footer Close buttons no longer get an \"x\" over their text."] = "拍賣場：Auctionator 及其他拍賣插件新增的面板與分頁保留其原本的外觀與版面，頁尾的關閉按鈕文字上也不再多出一個 \"x\"。"
L["Talents: the close button and the points footer end at the scroll bar instead of past the window edge."] = "天賦：關閉按鈕與點數頁尾在捲軸處結束，不再超出視窗邊緣。"
L["Window tabs keep their dark background instead of showing through."] = "視窗分頁保留其深色背景，不再透出後方。"
L["World map: the player arrow, party and raid dots, corpse and quest markers stay on the map art after a map view change during combat, including instance maps."] = "世界地圖：戰鬥中切換地圖檢視後，玩家箭頭、小隊與團隊圓點、屍體與任務標記仍會留在地圖美術上，副本地圖亦然。"
L["Native dropdown menus no longer show an empty square at the right of each row."] = "原生下拉選單的每一列右側不再出現空白方塊。"
L["Dropdown boxes in Blizzard windows, such as the Dungeon Finder type, end at their arrow instead of past the window edge."] = "暴雪視窗中的下拉框（例如地城搜尋器類型）在其箭頭處結束，不再超出視窗邊緣。"
L["Raid Information: the background covers the whole window, including the title, close button, last row and the Extend Raid Lock and Close buttons."] = "團隊資訊：背景覆蓋整個視窗，包含標題、關閉按鈕、最後一列，以及延長團隊鎖定與關閉按鈕。"
L["The Talents and Glyphs background now ends above the tabs and beside the dual spec tabs."] = "天賦與雕紋背景現在結束於分頁上方及雙天賦分頁旁。"
L["The Glyphs tab shows its native parchment background again, aligned with the glyph sockets."] = "雕紋分頁再次顯示原生羊皮紙背景，並與雕紋插槽對齊。"
L["Sliders in Blizzard windows, such as the Camera and Mouse options, are back to their normal size."] = "暴雪視窗中的滑桿（例如鏡頭與滑鼠選項）恢復正常大小。"
L["Hide Until Usable and Hide Outside Form/Stance"] = "可用前隱藏與不在形態/姿態時隱藏"
L["New Cooldown States: Hide Until Usable shows a spell only while it can be cast and is off cooldown (Overpower, Revenge, Victory Rush, Execute); low resources do not hide it. Hide Outside Form/Stance shows it only in the form or stance it needs. Both can close the gap or keep the place."] = "新的冷卻狀態：可用前隱藏只在法術可施放且未冷卻時顯示（壓制、復仇、勝利衝擊、斬殺）；資源不足不會將其隱藏。不在形態/姿態時隱藏只在所需的形態或姿態中顯示。兩者皆可補上空隙或保留位置。"
L["The + menu adds an Empty Slot that keeps a position free on the bar, to group icons."] = "+ 選單可新增空白欄位，在快捷列上保留一個位置，用於將圖示分組。"
L["Bars can switch to a Shaped swipe that follows round icons and takes a Swipe Color, instead of the client's dark square sweep."] = "條可切換為塑形轉圈，貼合圓形圖示並使用轉圈顏色，取代用戶端的深色方形轉圈。"
L["Cooldowns, Utility and Buffs bars plus custom bars and a FocusKick bar, tracked from your spellbook, cooldowns and auras. Lists are saved per talent group."] = "冷卻、輔助與增益條，以及自訂條與焦點打斷條，從你的法術書、冷卻與光環追蹤。清單依天賦組儲存。"
L["Aura or cooldown bars for player, target, focus or pet with textures, gradients, stack ticks and pandemic glow, arranged in groups."] = "玩家、目標、專注目標或寵物的光環或冷卻條，含材質、漸層、層數刻度與 pandemic 發光，並以群組排列。"
L["The + buttons above the bar icons open Retail's add menu: custom spell, item or slot, trinkets, racial, potions and your learned spells, or buffs and buff presets from the gold +"] = "條圖示上方的 + 按鈕會開啟正式版的新增選單：自訂法術、物品或欄位、飾品、種族技能、藥水及你已學會的法術，或從金色 + 新增增益與增益預設組合"
L["Passive proc trinkets in the trinket slots show their icon and the internal cooldown after each proc, with the proc buff while it lasts"] = "飾品欄位中的被動觸發飾品會顯示其圖示，並在每次觸發後顯示內部冷卻，觸發增益持續期間也會顯示"
L["Tracking bar textures include SharedMedia, and the FocusKick Cast Sound adds EllesmereUI and SharedMedia sounds to the Blizzard ones"] = "追蹤條材質包含 SharedMedia，焦點打斷施法音效在暴雪音效之外新增 EllesmereUI 與 SharedMedia 音效"
L["Light up EllesmereUI, Blizzard or ElvUI action buttons while an aura is active or missing"] = "在光環啟用或缺少時點亮 EllesmereUI、暴雪或 ElvUI 的動作按鈕"
L["Always show, dim, hide on cooldown or when ready, and glow when ready"] = "總是顯示、變暗、冷卻時或就緒時隱藏，以及就緒時發光"
L["Racials, healthstones, Wrath potions and buffs such as Heroism and Bloodlust"] = "種族技能、治療石、巫妖王藥水，以及英雄氣概與嗜血等增益"
L["Show an entry only when a chosen talent is learned"] = "只在學會指定天賦時顯示項目"
L["Utility bar options no longer switch to Buffs after a click, and the Cooldowns bar is no longer replaced by a second Buffs bar."] = "輔助條選項在點擊後不再切換為增益，冷卻條也不再被第二個增益條取代。"
L["Racials show once: the Utility bar no longer lists Arcane Torrent (and other racials with class variants) three times."] = "種族技能只顯示一次：輔助條不再將奧流之術（及其他有職業變體的種族技能）列出三次。"
L["A passive trinket in a trinket slot shows its own icon in the options instead of a question mark."] = "飾品欄位中的被動飾品在選項中顯示其本身的圖示，而非問號。"
L["Bars saved twice or under another bar's name (two Buffs bars and no Cooldowns) are repaired, so each built-in bar keeps its own icons and options."] = "重複儲存或以其他條名稱儲存的條（兩個增益條而沒有冷卻條）已修復，因此每個內建條都保有自己的圖示與選項。"
L["Auto Sized and Even Split bars with Retail backgrounds, borders and screen edge snapping, plus per-block margins, alignment, scale and colors."] = "自動尺寸與平均分配的條，具正式版背景、邊框與螢幕邊緣貼齊，以及各區塊的邊距、對齊、縮放與顏色。"
L["20 Wrath Blocks"] = "20 個巫妖王區塊"
L["Clock, FPS, latency, location, gold history, bags, durability, XP and reputation, dual spec, professions, travel, micro menu, currency and more."] = "時鐘、FPS、延遲、位置、金錢紀錄、背包、耐久度、經驗與聲望、雙天賦、專業技能、旅行、微型選單、貨幣等。"
L["Latency text is green, yellow or red by connection quality by default. A Latency swatch in Text Color switches back to it after picking another color."] = "延遲文字預設會依連線品質顯示為綠色、黃色或紅色。選擇其他顏色後，可透過文字顏色中的延遲樣本切換回來。"
L["Column tooltips with clickable rows and secure spell, item and macro lines"] = "欄位浮動提示，含可點擊的列以及安全的法術、物品與巨集行"
L["Every bar has a mover whose Element Options opens that bar's settings"] = "每個條都有移動器，其元素選項會開啟該條的設定"
L["Profiles from 0.2 are converted automatically"] = "0.2 版的設定檔會自動轉換"
L["Bars snapped to a screen edge or set to full length start in their place after login instead of needing Unlock Mode opened and closed."] = "貼齊螢幕邊緣或設為全長的條，登入後會直接出現在其位置，不必開關一次解鎖模式。"
L["The cast bar latency zone works for queued spells and remains visible during channels, with configurable color and millisecond text."] = "施法條延遲區段適用於佇列中的法術，引導期間仍保持可見，並可設定顏色與毫秒文字。"
L["Class, Power and Health Bars, Cast Bar, GCD Bar, Swing Timer and Totem Bar, each element with its own Unlock Mode mover. Older profiles migrate once."] = "職業、能量與生命條、施法條、GCD 條、揮擊計時器與圖騰列，每個元素都有各自的解鎖模式移動器。舊設定檔會遷移一次。"
L["Main hand, off hand and ranged swings from the combat log, with queued Heroic Strike, Cleave and Maul, parry haste and speed changes."] = "從戰鬥紀錄取得主手、副手與遠程揮擊，包含佇列中的英勇打擊、順劈斬與槌擊、招架加速及速度變化。"
L["Bar textures include textures from SharedMedia and other addons"] = "條材質包含來自 SharedMedia 及其他插件的材質"
L["Vertical bars, Retail texts, gradients, thresholds, tick marks and smoothing"] = "垂直條、正式版文字、漸層、門檻、刻度標記與平滑"
L["Death Knight rune order and countdowns, combo points, or Blizzard's own art"] = "死亡騎士符文順序與倒數、連擊點數，或暴雪原本的美術"
L["Channel ticks, latency, total duration and uninterruptible colors"] = "引導刻度、延遲、總持續時間與不可中斷顏色"
L["Totem icons and timers, and a movable Call Totem Bar"] = "圖騰圖示與計時器，以及可移動的召喚圖騰列"
L["The Call Totem Bar no longer resizes or moves during combat; changes apply when combat ends."] = "召喚圖騰列在戰鬥中不再調整大小或移動；變更會在戰鬥結束時套用。"
L["The player cast bar shows the channeled spell's name instead of \"Channeling\"."] = "玩家施法條顯示引導法術的名稱，而非 \"Channeling\"。"
L["Class icons in the EUI themes, status orbs, notes in the details line, faction banners and hover highlight, with borders and accent colors."] = "EUI 主題中的職業圖示、狀態圓球、詳細資訊行中的備註、陣營旗幟與滑鼠移過高亮，含邊框與強調色。"
L["Accepts group invites from friends, and optionally from guild members, and closes the popup."] = "接受來自好友的隊伍邀請，並可選擇接受公會成員的邀請，然後關閉彈出視窗。"
L["The window stays native but rows still get class icons and colored names"] = "視窗維持原生外觀，但每一列仍會有職業圖示與彩色名稱"
L["Auto Accept picks quests from NPC dialogs, with Prevent Multi Quest Accept, and Auto Turn In completes single-reward quests. Hold Shift to skip."] = "自動接受會從 NPC 對話中接取任務，含防止一次接取多個任務；自動交付會完成只有單一獎勵的任務。按住 Shift 可略過。"
L["Uses the item of your tracked quest, found in the quest log, and only holds the key while there is an item to use."] = "使用在任務日誌中找到的追蹤任務物品，且只在有物品可用時佔用該按鍵。"
L["The top line uses the accent color and Line Color tints the header divider"] = "頂端線條使用強調色，線條顏色會為標題分隔線著色"
L["/eqt show, /eqt hide and /eqt toggle"] = "/eqt show、/eqt hide 與 /eqt toggle"
L["Clear your focus by clicking the focus frame (Shift + Right Click by default, or Ctrl/Alt + Right Click, Middle Click, Shift + Left Click). Set it on the Focus frame page. Works in combat."] = "點擊專注目標框架即可清除專注目標（預設為 Shift + 右鍵，或 Ctrl/Alt + 右鍵、中鍵、Shift + 左鍵）。在專注目標框架頁面設定。戰鬥中也有效。"
L["Two new debuff filter modes: Raid Debuffs shows the common raid debuffs from anyone (armor, spell and physical damage taken, crit taken, attack power, attack and cast speed, healing taken, Judgements and Hunter's Mark), and Own and Raid Debuffs adds yours."] = "兩種新的減益效果篩選模式：團隊減益效果會顯示任何人施加的常見團隊減益效果（護甲、受到的法術與物理傷害、受到的致命一擊、攻擊強度、攻擊與施法速度、受到的治療、審判與獵人印記），自己的與團隊減益效果則會再加上你的減益效果。"
L["Type Icon Position puts the icon of the player's highest dispellable debuff type on a point of the health bar, with its size and offsets in the cog. Only Dispellable by You now sits beside it and narrows the overlay, icon and border colors alike."] = "類型圖示位置會將玩家最高可驅散減益類型的圖示放在生命條的某個點上，其大小與偏移在齒輪中設定。僅你能驅散的現在位於其旁邊，並同樣縮限覆蓋層、圖示與邊框顏色。"
L["The focus frame gets the aura Border Style, size and color settings, as player and target have."] = "專注目標框架新增光環邊框樣式、大小與顏色設定，與玩家及目標相同。"
L["Player, target and focus show incoming heals past the health fill: yours and other players' in their own colors, from LibHealComm-4.0 (only healers running a HealComm addon are seen)."] = "玩家、目標與專注目標會在生命填充之後顯示即將到來的治療：你的與其他玩家的治療各有自己的顏色，資料來自 LibHealComm-4.0（只會看到執行 HealComm 插件的治療者）。"
L["The debuff filters can now show or hide Sated, Exhaustion and the other Bloodlust lockout debuffs. They stay hidden by default."] = "減益效果篩選現在可以顯示或隱藏滿足、力竭及其他嗜血冷卻減益效果。預設保持隱藏。"
L["Left, Right, Center and Extra Text, the Bottom Text Bar texts and Power Percent each have an Outline choice under Size: None, Outline, Thick Outline or Shadow, or the module default."] = "左側、右側、置中與額外文字、底部文字列的文字及能量百分比，在大小下方各有外框選項：無、外框、粗外框或暗影，或模組預設。"
L["Anchor, growth, icons per row, duration and stack text, textured borders and dispel rings. Target and focus get Purgeable Buff Glow."] = "錨點、增長方向、每列圖示數、持續時間與層數文字、材質邊框與驅散光環。目標與專注目標新增可淨化增益發光。"
L["Every combat indicator style now shows, and highlighted portraits fit their shape instead of overflowing it."] = "所有戰鬥指示器樣式現在都會顯示，高亮的頭像也會貼合其形狀而不再溢出。"
L["Player, target, focus and boss health bars show estimated damage shields with Retail's Absorb Style, Opacity, Color, Placement, Show Overshield and Show on Boss Frames"] = "玩家、目標、專注目標與首領生命條會顯示估算的傷害護盾，具正式版的吸收樣式、不透明度、顏色、擺放位置、顯示溢出護盾與在首領框架上顯示"
L["Mana or Mana + Form Power, with a separate form bar"] = "法力或法力 + 形態能量，另有獨立的形態條"
L["Threat %, a pet power bar and the pet happiness icon"] = "仇恨 %、寵物能量條與寵物快樂度圖示"
L["Pooled aura indicators on the health bar with Use Indicator Layout"] = "使用指示器配置，在生命條上集中顯示光環指示器"
L["Fill, full, gradient and sharp gradient overlays in the dispel color"] = "以驅散顏色顯示的填充、全滿、漸層與清晰漸層覆蓋層"
L["Under Classic WoW UI and Blizzard Style, the leader crown sits on the portrait's top corner, as on the original frames, instead of inside the health bar."] = "在經典 WoW 介面與暴雪風格下，隊長皇冠位於頭像的頂角，與原始框架相同，而非在生命條內。"
L["The party leader icon on unit frames shows on the leader only instead of on several party members."] = "單位框架上的隊長圖示只會顯示在隊長身上，而非多位小隊成員身上。"
L["Set Focus and Clear Focus in the unit frame right-click menu work out of combat without the 'blocked from an action' popup; in combat they are hidden."] = "單位框架右鍵選單中的設為專注目標與清除專注目標，在脫離戰鬥時可正常使用，不會跳出「已被禁止執行動作」的提示；戰鬥中會隱藏。"
L["Unit frame bars and portraits no longer get moved into scroll frames when !!!ClassicAPI is installed."] = "安裝 !!!ClassicAPI 時，單位框架的條與頭像不再被移入捲動框架。"
L["Important Cast Glow is hidden for target and focus cast bars; the Wrath client cannot tell which spells are important."] = "目標與專注目標施法條的重要施法發光已隱藏；巫妖王用戶端無法判斷哪些法術是重要的。"
L["Channel cast bars show the spell's name instead of \"Channeling\"."] = "引導施法條顯示法術名稱，而非 \"Channeling\"。"
L["Boss frames now update health, power and text while the boss is not your target or focus."] = "首領框架現在在首領不是你的目標或專注目標時，也會更新生命、能量與文字。"
L["Visibility conditions (combat, group, and hiding without a target) now apply to the frames instead of stopping with an error, so the Visibility menu's boxes also tick right away."] = "可見性條件（戰鬥、隊伍，以及沒有目標時隱藏）現在會套用至框架，不再因錯誤而中止，因此可見性選單的方框也會立即勾選。"
L["Classic WoW UI power bars now stay inside the frame art: the art's rim draws over the power bar as it does over the health bar."] = "經典 WoW 介面的能量條現在保持在框架美術內：美術邊緣會覆蓋在能量條上，就像覆蓋生命條一樣。"
L["Classic WoW UI now gives every unit frame the original green health bar instead of class colors. Returning to the EllesmereUI look restores your colors."] = "經典 WoW 介面現在讓每個單位框架使用原始的綠色生命條，而非職業顏色。切換回 EllesmereUI 外觀會恢復你的顏色。"
L["Classic WoW UI power bars use the original game colors (deep blue mana, red rage, yellow energy) instead of the EllesmereUI palette. Other looks keep the palette."] = "經典 WoW 介面的能量條使用原始遊戲顏色（深藍色法力、紅色怒氣、黃色能量），而非 EllesmereUI 色盤。其他外觀保留色盤。"
L["Text outlines now apply to the live frames, not only the options preview."] = "文字外框現在會套用至實際框架，而不只是選項預覽。"
L["Unit frames no longer fail to load on setups whose mask textures come back empty (absorb bar error at login)."] = "在遮罩材質傳回空值的環境下，單位框架不再載入失敗（登入時的吸收條錯誤）。"
L["Icons shown by spell ID now show the right icon or a question mark, never an empty square."] = "以法術 ID 顯示的圖示現在會顯示正確的圖示或問號，不再是空白方塊。"
L["The faction indicator no longer errors in mercenary mode, and Retail-only PvP styles use the Wrath PvP icon."] = "陣營指示器在傭兵模式下不再出錯，正式版專屬的 PvP 樣式改用巫妖王的 PvP 圖示。"
L["Level text no longer errors with Font not set when frames are first created."] = "首次建立框架時，等級文字不再出現 Font not set 錯誤。"
L["Like Retail 9.4, the Experience Bar section opens with XP Bar Style: EllesmereUI for the EUI bar, Luxthos for the EUI bar in the Luxthos WeakAura layout, or Blizz Default for Blizzard's own XP and reputation bars. It replaces Enable Experience Bar and the Apply Luxthos Layout button."] = "如同正式版 9.4，經驗值條區塊開頭為經驗值條樣式：EllesmereUI 使用 EUI 條，Luxthos 為採用 Luxthos WeakAura 版面的 EUI 條，暴雪預設則使用暴雪本身的經驗與聲望條。它取代了啟用經驗條與套用 Luxthos 版面按鈕。"
L["Like Retail 9.4, any horizontal bar can show the classic gryphons at its left end, right end or both, from the End Caps menu at the end of LAYOUT. The cog sets their size and offsets, and Apply to All copies them to every bar. The live preview shows them too."] = "如同正式版 9.4，任何水平條都可在其左端、右端或兩端顯示經典獅鷲，從版面配置末端的端飾選單設定。齒輪可設定其大小與偏移，套用至所有會將其複製到每個條。即時預覽也會顯示。"
L["The XP bar gets Retail's Quest XP Overlay (completed quests in green, incomplete in gold), dividers with Smart Ticks, gradient fills, background and rested colors, and seven text positions showing values, completed quest XP, XP per hour, time to level and time played. Apply Luxthos Layout recreates the popular Luxthos XP bar WeakAura, with Show at Max Level, a spark and rested XP after quest XP."] = "經驗值條新增正式版的任務經驗值覆蓋層（已完成任務為綠色，未完成為金色）、含智慧刻度的分隔線、漸層填充、背景與休息顏色，以及七個文字位置，可顯示數值、已完成任務經驗值、每小時經驗值、升級所需時間與遊戲時間。套用 Luxthos 版面會重現熱門的 Luxthos 經驗條 WeakAura，含滿級時顯示、火花與任務經驗值後的休息經驗值。"
L["Buttons holding an equipped item, such as a trinket, can show a border in its rarity color. Off by default."] = "放置已裝備物品（例如飾品）的按鈕，可顯示其稀有度顏色的邊框。預設關閉。"
L["Four extra bars, off by default, each with its own keybinds, Unlock Mode mover and the full Bar Display settings. Warriors, Druids, Rogues and Priests see which stance or form shares a bar's slots."] = "四個額外快捷列，預設關閉，各有自己的快捷鍵、解鎖模式移動器與完整的條顯示設定。戰士、德魯伊、盜賊與牧師可看到哪個姿態或形態共用該快捷列的欄位。"
L["Circle and Portrait draw round icons, Diamond, Hexagon and Shield crop the icon to the shape, and Square and Curved Square add a shaped outline. Set per bar, including pet and stance."] = "圓形與頭像繪製圓形圖示，菱形、六邊形與護盾將圖示裁切成該形狀，方形與圓角方形則加上造型外框。可依快捷列設定，包含寵物與姿態列。"
L["Type /kb, hover a button and press a key to bind it, including modifiers, mouse buttons and the wheel. Right-click clears; Cancel or Esc undoes."] = "輸入 /kb，將滑鼠移到按鈕上並按下按鍵即可綁定，包含輔助鍵、滑鼠按鍵與滾輪。右鍵清除；取消或 Esc 可復原。"
L["Per-bar text, borders, backgrounds, orientation and growth, the Retail button animations and visibility engine, and Bar 1 modifier paging."] = "各快捷列的文字、邊框、背景、方向與增長，正式版的按鈕動畫與可見性引擎，以及快捷列 1 的輔助鍵換頁。"
L["Shift+1 shows as S1, Control+1 as C1, mouse buttons as M4 and the wheel as MwU/MwD"] = "Shift+1 顯示為 S1，Control+1 為 C1，滑鼠按鍵為 M4，滾輪為 MwU/MwD"
L["Shrink the bag bar to a single backpack button"] = "將背包列縮小為單一背包按鈕"
L["Square micro menu and bag bar, flat XP and reputation bars and movable buffs and debuffs"] = "方形微型選單與背包列、扁平經驗與聲望條，以及可移動的增益與減益效果"
L["Bar 1 paging arrows change the page without the \"blocked from an action only available to the Blizzard UI\" message."] = "快捷列 1 的換頁箭頭可切換頁面，不再出現 \"blocked from an action only available to the Blizzard UI\" 訊息。"
L["Changing stance no longer reveals a duplicate Blizzard stance and pet bar."] = "切換姿態時不再出現重複的暴雪姿態列與寵物列。"
L["Spells can be dropped on Bar 1 while the Blizzard bar art is hidden."] = "隱藏暴雪快捷列美術時，仍可將法術拖放至快捷列 1。"
L["Player Buffs keep growing downward as rows are added."] = "新增列數時，玩家增益會持續向下增長。"
L["The XP and reputation bars no longer error on their first update."] = "經驗與聲望條在首次更新時不再出錯。"
L["Create Soulstone reminders, including custom spell reminders, only appear for Warlocks."] = "製造靈魂石提醒（包含自訂法術提醒）只會對術士顯示。"
L["A Holy-only reminder for your Seal of Wisdom, including when another seal is active."] = "僅限神聖天賦的智慧聖印提醒，包含啟用其他聖印時。"
L["One click casts your group buff, such as Fortitude, Gift of the Wild or Arcane Brilliance, at its highest rank on the first member missing it."] = "一鍵以最高等級對第一位缺少的成員施放你的隊伍增益，例如真言術：韌、野性賜福或秘法光輝。"
L["Auras, presences, aspects, shields, weapon imbues, poisons, pets, Soulstone and Healthstone, plus flask, elixir and food with bag counts."] = "光環、靈氣、守護、護盾、武器強化、毒藥、寵物、靈魂石與治療石，以及精煉藥劑、藥劑與食物，並顯示背包中的數量。"
L["Reminder sounds include SharedMedia sounds, even from packs that load later"] = "提醒音效包含 SharedMedia 音效，即使來自較晚載入的套件也一樣"
L["World, normal and heroic dungeons and raids, or in combat, with Show Below timers"] = "野外、普通與英雄地城及團隊副本，或戰鬥中，含低於此值時顯示計時器"
L["Talent reminders for Wrath zones and your current instance"] = "巫妖王區域與你目前副本的天賦提醒"
L["Your own aura ID reminders and a healer mana Ready Check Warning"] = "你自己的光環 ID 提醒，以及治療者法力的準備確認警告"
L["Middle-click hides a reminder until the next loading screen"] = "中鍵點擊可隱藏提醒直到下一次讀取畫面"
L["Turning off Runeforging now hides the Death Knight rune reminder."] = "關閉符文熔鑄現在會隱藏死亡騎士符文提醒。"
L["Adding zones to an older talent reminder no longer errors, and the new zones apply right away."] = "為舊的天賦提醒新增區域不再出錯，新區域會立即套用。"
L["A coin in the bag header marks items as junk: click it, then click items. Grey and marked items go to a Junk category, and a Sell Junk button appears next to the coin at merchants. Its cog adds a coin badge on marked items."] = "背包標題列中的硬幣可將物品標記為垃圾：點擊它，然後點擊物品。灰色與已標記的物品會歸入垃圾分類，與商人交易時硬幣旁會出現販賣垃圾按鈕。其齒輪可在已標記物品上加上硬幣標記。"
L["Bag keybinds open and close the existing layout during combat. Layout refreshes wait until combat ends."] = "背包快捷鍵在戰鬥中會開關現有的版面。版面刷新會等到戰鬥結束。"
L["A sidebar with All Items, OneBag and MultiBag views, pinned and recent items, Retail categories for Wrath items and your own categories."] = "側欄提供所有物品、單一背包與多重背包檢視、釘選與最近物品、對應巫妖王物品的正式版分類，以及你自己的分類。"
L["OneBag merges stacks and sorts by bag type, MultiBag sorts each bag, with Sort to Bottom and Randomize."] = "單一背包會合併堆疊並依背包類型排序，多重背包則各自排序每個背包，並提供排序至底部與隨機排列。"
L["A cog beside the search opens the Bags options, or the Bank page at the bank"] = "搜尋旁的齒輪會開啟背包選項，在銀行時則開啟銀行頁面"
L["Each saved character in the Characters list has an x to delete its data"] = "角色清單中每個已儲存角色都有 x 可刪除其資料"
L["Quality borders, quest marks, item level, BoE text, set names and dimmed junk"] = "品質邊框、任務標記、物品等級、裝備綁定文字、套裝名稱與變暗的垃圾物品"
L["Group the bank by category, with a sidebar"] = "依分類將銀行分組，並附側欄"
L["With Enable Bags off, the default bag functions are no longer replaced, avoiding blocked action errors from tainted bag code."] = "關閉啟用背包時，不再取代預設的背包函式，避免受汙染的背包程式碼造成禁止動作錯誤。"
L["Opening the Characters list no longer errors."] = "開啟角色清單不再出錯。"
L["Gold sale ads with websites or cash prices, including 5000G=20 bucks and disguised W.W.W addresses, are filtered by default in your selected chat scopes."] = "附有網站或現金價格的金幣販售廣告，包括 5000G=20 bucks 與偽裝的 W.W.W 網址，預設會在你選擇的聊天範圍中被過濾。"
L["Unsupported server channel notices such as NOT_IN_LFG no longer cause the native chat formatter to error."] = "不支援的伺服器頻道通知（例如 NOT_IN_LFG）不再造成原生聊天格式化程式出錯。"
L["Optional spam filtering with a repeat window, sender matching and public, group or whisper controls."] = "可選的垃圾訊息過濾，含重複時間範圍、發送者比對，以及公共、隊伍或密語控制。"
L["Background, divider, input position, Retail border and tabs over the native dock, plus a sidebar with friends, guild, copy, channels and settings."] = "背景、分隔線、輸入框位置、正式版邊框與原生停靠區上的分頁，以及含好友、公會、複製、頻道與設定的側欄。"
L["Retail timestamps, short channel names, class colored names, link tooltips, whisper sounds, saved chat history and Retail URL and copy windows."] = "正式版時間戳記、簡短頻道名稱、職業顏色名稱、連結浮動提示、密語音效、已儲存的聊天紀錄，以及正式版網址與複製視窗。"
L["Show Hidden Messages lists the last 200 lines the spam filter hid this session, with time, reason, channel and sender. Clear Filter History is now Reset Repeat Memory."] = "顯示隱藏的訊息會列出本次登入時段中垃圾訊息過濾隱藏的最後 200 行，含時間、原因、頻道與發送者。清除過濾紀錄現已改為重置重複記憶。"
L["The trade ad preset also hides LFW (looking for work) crafting ads."] = "交易廣告預設組合也會隱藏 LFW（求工作）的製作廣告。"
L["Right-click the chat in Unlock Mode to open its Display settings"] = "在解鎖模式中右鍵點擊聊天視窗即可開啟其顯示設定"
L["Restyled chat bubbles with per-channel toggles and hiding in instances"] = "重新設計的對話泡泡，含各頻道開關與在副本中隱藏"
L["The chat fades after a delay and comes back on mouseover"] = "聊天視窗在一段時間後淡出，滑鼠移過時重新出現"
L["Copy Chat copies the chat tab you are looking at instead of the last tab you right-clicked, which could show \"(No chat history)\"."] = "複製聊天會複製你正在查看的聊天分頁，而非你上次右鍵點擊的分頁（那可能會顯示 \"(No chat history)\"）。"
L["Fixed a \"SetPoint(): is dependent on this\" error when styling some NPC chat bubbles."] = "修正為某些 NPC 對話泡泡套用樣式時出現的 \"SetPoint(): is dependent on this\" 錯誤。"
L["The guild recruitment filter no longer hides raid ads that mention a guild, such as \"<Frost> LF 1 heal ICC25\"; only LF guild phrases count."] = "公會招募過濾不再隱藏提到公會的團隊招募廣告，例如 \"<Frost> LF 1 heal ICC25\"；只有尋找公會的用語才算。"
L["GM whispers and messages are never hidden by the spam filter."] = "GM 密語與訊息永遠不會被垃圾訊息過濾隱藏。"
L["Spam filter keywords ignore case for accented letters too, so promoção also hides PROMOÇÃO."] = "垃圾訊息過濾關鍵字對帶重音符號的字母也不分大小寫，因此 promoção 也會隱藏 PROMOÇÃO。"
L["The trade ad and guild recruitment filters follow the Public Chat setting, and the spam filter does no work while every filter is off."] = "交易廣告與公會招募過濾會依循公共聊天設定，且所有過濾都關閉時，垃圾訊息過濾不會執行任何運算。"
L["The sidebar shows on first load, and tabs and toggles update right away."] = "側欄在首次載入時顯示，分頁與開關會立即更新。"
L["The main chat keeps its Unlock Mode position instead of being reset by the dock."] = "主聊天視窗會保留其解鎖模式位置，不再被停靠區重設。"
L["A saved chat opacity of 0 resets once to the Retail default."] = "已儲存的聊天不透明度若為 0，會重設一次為正式版預設值。"
L["Square, rectangular, circle and textured circle maps, with border size, opacity, textured styles and custom, accent or class colors."] = "方形、矩形、圓形與材質圓形地圖，含邊框大小、不透明度、材質樣式，以及自訂、強調色或職業顏色。"
L["Addon buttons collect into the Retail flyout with a grid, grow direction and Shift-drag Free Move."] = "插件按鈕會收進正式版的彈出選單，含網格、增長方向與 Shift 拖曳自由移動。"
L["A vanilla ring and zone banner with native zoom buttons"] = "原版圓環與區域橫幅，含原生縮放按鈕"
L["Clock and zone boxes in ten positions, plus coordinates, FPS and latency, and difficulty text"] = "時鐘與區域框有十種位置，另有座標、FPS 與延遲，以及難度文字"
L["Guild and friends at a glance; left-click whispers, right-click invites"] = "一眼掌握公會與好友；左鍵點擊密語，右鍵點擊邀請"
L["Menu actions open Blizzard windows through secure calls, avoiding blocked action errors."] = "選單動作透過安全呼叫開啟暴雪視窗，避免禁止動作錯誤。"
L["Pick Classic WoW UI for Damage Meters on the Style page: each window gets the classic tooltip border, a tooltip header band and vanilla header icons, and keeps every EllesmereUI meter feature."] = "在樣式頁面為傷害統計選擇經典 WoW 介面：每個視窗都會有經典浮動提示邊框、浮動提示標題帶與原版標題圖示，並保留 EllesmereUI 的所有統計功能。"
L["A spell's breakdown tooltip shows its Spell ID, and each spell row in the detailed window ends with its ID."] = "法術的明細浮動提示會顯示其法術 ID，詳細視窗中的每一列法術結尾也會顯示其 ID。"
L["Consumed shield absorbs count toward Healing Done and HPS when the caster can be identified, with an Absorbs Done view."] = "可辨識施法者時，被消耗的護盾吸收量會計入造成治療與 HPS，並提供吸收量檢視。"
L["Flat body, accent header, Atrocity bars and header icons for Settings, Segment, Meter Type and Reset, with up to five windows."] = "扁平主體、強調色標題、Atrocity 條，以及設定、區段、統計類型與重設的標題圖示，最多五個視窗。"
L["Up to 15 spells and the top three targets on hover, death recaps with health at each hit, and a per-player focus view."] = "滑鼠移過時顯示最多 15 個法術與前三名目標、含每次受擊時生命值的死亡回顧，以及單一玩家的焦點檢視。"
L["SharedMedia bar textures load whether a profile stores them in Damage Meters or EllesmereUI format"] = "無論設定檔以傷害統計或 EllesmereUI 格式儲存，SharedMedia 條材質都會載入"
L["An icon strip and bar window of your casts, including failed and interrupted ones"] = "你的施法圖示列與條狀視窗，包含失敗與被打斷的施法"
L["A standalone combat timer with its own Unlock Mode element"] = "獨立的戰鬥計時器，具有自己的解鎖模式元素"
L["Windows snap to each other; locked windows cannot move, resize or close"] = "視窗會互相貼齊；鎖定的視窗無法移動、調整大小或關閉"
L["Keybinds for Reset Data and Show / Hide Windows"] = "重設資料與顯示 / 隱藏視窗的快捷鍵"
L["Specialization icons from talent data and paced group inspection"] = "來自天賦資料的專精圖示，以及分批進行的隊伍觀察"
L["Load an action menu only in your primary or secondary talent group, and let two menus share one keybind across specs."] = "只在你的主要或次要天賦組載入動作選單，並讓兩個選單跨專精共用一個快捷鍵。"
L["Hold a key, point or scroll to choose, release to fire. Up to 16 palettes of 20 entries in ring, arc, fan or grid layouts."] = "按住按鍵，指向或捲動以選擇，放開即施放。最多 16 組調色盤，每組 20 個項目，可用環形、弧形、扇形或網格版面。"
L["An Action Menu entry fans out up to 8 actions from another palette, one level out from the ring."] = "動作選單項目會從另一組調色盤展開最多 8 個動作，位於環形外一層。"
L["Accent, class or custom color for the selected entry, needle and nested highlight"] = "所選項目、指針與巢狀高亮可使用強調色、職業顏色或自訂顏色"
L["Set the gap between a nested menu and its entry, and the nested icon size"] = "設定巢狀選單與其項目之間的間距，以及巢狀圖示大小"
L["Reverse which way a wheel tick moves the selection"] = "反轉滾輪每一格移動選取項目的方向"
L["Assign Key captures the next key with modifiers and asks before rebinding"] = "指定按鍵會擷取下一個按鍵（含輔助鍵），並在重新綁定前先詢問"
L["Keep the menu open on release and fire with a Select key"] = "放開時保持選單開啟，並以選擇鍵施放"
L["Red when out of range, blue when short of power, grey when unusable"] = "超出範圍時為紅色，能量不足時為藍色，無法使用時為灰色"
